INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera pittieri', 'Monstera pittieri', 6.0, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Contains calcium oxalate crystals; ingestion causes oral irritation, drooling, and difficulty swallowing in cats and dogs.', 'Average', '{filtered_indirect}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings. Check soil moisture at the root zone before watering again.', 60, 80, 'Intermediate', 'A rare and premium tropical aroid with deeply lobed, fenestrated leaves that mature into dramatic split foliage. Highly prized by collectors for its exotic appearance and slower growth habit compared to common Monsteras.', 'Indoor', true, true, 'Sap and leaves contain calcium oxalate crystals; ingestion causes oral pain, swelling, and difficulty swallowing. Skin contact may cause dermatitis.', false, NULL, true, 'Spring – Summer', 'Slow', 'Medium', '{Well-draining,Rich,Moisture-retaining}', 'Central America (Costa Rica, Panama)', 200, 120, true, 'https://inaturalist-open-data.s3.amazonaws.com/photos/109135403/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/109135403/medium.jpg', true, 952585, 952585, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera subpinnata', 'Monstera subpinnata', 6.0, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Contains calcium oxalate crystals. Ingestion causes oral irritation, drooling, difficulty swallowing, and gastrointestinal upset in cats and dogs.', 'Frequent', '{filtered_indirect}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings. This aroid prefers consistently moist but not waterlogged conditions.', 60, 85, 'Intermediate', 'A rare tropical aroid with deeply lobed, non-fenestrated leaves that mature into distinctive pinnate segments. Slower-growing than Monstera deliciosa, it thrives in warm, humid conditions and is prized by collectors for its unique foliage architecture.', 'Indoor', true, true, 'Calcium oxalate crystals in leaves and stems cause oral pain, burning sensation on the tongue and lips, and gastrointestinal irritation if ingested. Sap may irritate skin and eyes upon contact.', false, NULL, true, 'Spring – Summer', 'Slow', 'Medium', '{Well-draining,Loamy,Rich}', 'Central and South America (Mexico to Costa Rica)', 200, 150, true, 'https://inaturalist-open-data.s3.amazonaws.com/photos/21831894/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/21831894/medium.jpg', true, 816755, 816755, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera costaricensis', 'Monstera costaricensis', 5.5, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Contains calcium oxalate crystals. Ingestion causes oral irritation, drooling, difficulty swallowing, and gastrointestinal upset in cats and dogs.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings. Check soil moisture with finger at surface.', 50, 80, 'Intermediate', 'A tropical aroid with distinctive deep lobed and fenestrated leaves, smaller and more delicate than Monstera deliciosa. Prized for its compact growth habit and dramatic foliage in indoor plant collections.', 'Indoor', true, true, 'Contains calcium oxalate crystals. Ingestion causes intense oral pain, burning, swelling of lips and tongue, and gastrointestinal irritation. Sap may irritate skin and eyes on contact.', false, NULL, true, 'Spring – Summer', 'Moderate', 'Medium', '{Well-draining,Rich,Loamy}', 'Central America (Costa Rica and Panama)', 150, 90, true, 'https://inaturalist-open-data.s3.amazonaws.com/photos/14656550/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/14656550/medium.jpeg', true, 702146, 702146, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera ngabensis', 'Monstera ngabensis', 5.5, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Contains calcium oxalate crystals; ingestion causes oral irritation, drooling, and difficulty swallowing in cats and dogs.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings. Check soil moisture at this depth before re-watering.', 60, 85, 'Intermediate', 'A rare, climbing aroid from Central Africa with deeply lobed or fenestrated mature leaves and aerial roots, highly valued by collectors for its unique foliage. Requires consistent warmth, high humidity, and bright indirect light to thrive indoors.', 'Indoor', true, true, 'Sap and leaves contain calcium oxalate crystals; ingestion causes mouth and throat burning, swelling, and gastrointestinal distress. Skin contact may cause dermatitis.', false, NULL, false, NULL, 'Moderate', 'Medium', '{Well-draining,Loamy,Rich}', 'Central Africa (Cameroon, Gabon region)', 200, 150, false, NULL, NULL, true, 1639747, 1639747, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera standleyana', 'Monstera standleyana', 6.0, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Leaves and stems contain calcium oxalate crystals; ingestion causes oral irritation, drooling, and difficulty swallowing in cats and dogs.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings; keep soil consistently moist during growing season but never waterlogged.', 60, 80, 'Intermediate', 'A trailing to vining aroid with elongated, deeply lobed or fenestrated leaves, smaller and more delicate than Monstera deliciosa. Prized as an indoor specimen for its compact growth and sculptural foliage; excellent for hanging baskets or moss poles.', 'Indoor', true, true, 'Contains insoluble calcium oxalate crystals; ingestion causes oral burning, swelling of lips and mouth, and difficulty swallowing. Sap may irritate skin on contact.', false, NULL, true, 'Spring – Summer', 'Moderate', 'Medium', '{Well-draining,Loamy,Rich}', 'Central America and Mexico', 150, 60, true, 'https://static.inaturalist.org/photos/213934766/square.jpg', 'https://static.inaturalist.org/photos/213934766/medium.jpg', true, 777170, 777170, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera glaucescens', 'Monstera glaucescens', 6.0, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Contains insoluble calcium oxalate crystals that cause oral irritation, drooling, and difficulty swallowing in cats and dogs if ingested.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings; water when moisture at this depth is no longer present.', 60, 80, 'Intermediate', 'A tropical aroid climber with distinctive waxy, glaucous (powdery-grey) foliage and a more compact, upright habit than Monstera deliciosa. Prized for its unique silvery leaf appearance and moderate growth rate, suitable for bright indirect indoor environments.', 'Indoor', true, true, 'Contains insoluble calcium oxalate crystals that cause oral irritation, burning sensation, and swelling of the lips, mouth, and throat if ingested. Sap may irritate skin on contact.', false, NULL, true, 'Spring – Summer', 'Moderate', 'Medium', '{Well-draining,Loamy,Rich}', 'Central and South America', 200, 90, true, 'https://inaturalist-open-data.s3.amazonaws.com/photos/52406081/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/52406081/medium.jpeg', true, 952577, 952577, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera buseyi', 'Monstera buseyi', 6.0, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Contains calcium oxalate crystals; ingestion causes oral irritation, drooling, and difficulty swallowing in cats and dogs.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings. Water thoroughly when the soil at this depth feels dry to the touch.', 60, 85, 'Intermediate', 'A rare tropical aroid with deeply lobed or pinnately cut leaves, smaller and more delicate than common Monstera deliciosa. Valued by collectors for its unique foliage and slower, more compact growth habit.', 'Indoor', true, true, 'Contains calcium oxalate crystals; ingestion causes oral burning, lip swelling, and throat irritation. Sap may cause skin irritation in sensitive individuals.', false, NULL, true, 'Spring – Summer', 'Slow', 'Medium', '{Well-draining,Loamy,Rich}', 'Central America (Mexico and Central American rainforests)', 120, 90, true, 'https://inaturalist-open-data.s3.amazonaws.com/photos/58570599/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/58570599/medium.jpg', true, 952570, 952570, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera epipremnoides', 'Monstera epipremnoides', 6.0, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Contains calcium oxalate crystals; ingestion causes oral irritation, burning, and difficulty swallowing in pets. Contact with skin or mucous membranes may cause irritation.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings; do not allow the root zone to dry completely. Check soil moisture at the surface weekly during the growing season.', 60, 80, 'Intermediate', 'A climbing or trailing aroid native to Central America, Monstera epipremnoides is a rare relative of the fenestrated Monstera deliciosa. It produces deeply lobed (non-fenestrated) leaves with distinctive elongated segments and grows as a moderate-paced epiphytic vine, prized by collectors for its unique foliage and architectural growth habit.', 'Indoor', true, true, 'Contains insoluble calcium oxalate crystals. Ingestion causes oral and throat irritation, swelling, and difficulty swallowing. Skin or eye contact may cause localized irritation.', false, NULL, false, NULL, 'Moderate', 'Medium', '{Well-draining,Loamy,Rich}', 'Central America', 150, 60, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/118582983/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/118582983/medium.jpeg', true, 952573, 952573, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera maderaverde', 'Monstera maderaverde', 6.0, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Contains calcium oxalate crystals; ingestion causes oral irritation, difficulty swallowing, and gastrointestinal upset in cats and dogs.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings. Check soil moisture at finger depth before watering.', 60, 80, 'Beginner', 'A tropical aroid with large, deeply lobed or fenestrated green leaves and a vigorous climbing or trailing habit. Prized for dramatic foliage and excellent air-purifying qualities in indoor spaces.', 'Indoor', true, true, 'Sap and leaf tissue contain calcium oxalate crystals; ingestion causes mouth and throat irritation, burning sensation, and difficulty swallowing. Skin contact may cause mild dermatitis.', false, NULL, true, 'Spring – Summer', 'Fast', 'Low', '{Well-draining,Loamy,Rich}', 'Central and South America', 200, 150, true, NULL, NULL, true, 952581, 952581, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Ophrys fusca forestieri', 'Dark bee-orchid', 6.0, 7.5, false, '{Seeds,Division}', true, NULL, '2026-06-08 15:02:20.60003+00', NULL, 'Average', '{full_sun,part_shade}', 'Perennial', NULL, 'Keep substrate moist during active growth; allow to dry slightly between waterings during dormancy. Check moisture at 2–3 cm depth.', 50, 70, 'Advanced', 'A Mediterranean terrestrial orchid with dark, velvety sepals and a distinctive labellum mimicking female bee morphology to attract pollinators. Highly specialized and challenging in cultivation, requiring precise dormancy cycles and well-draining orchid substrate.', 'Outdoor', false, false, NULL, true, 'Spring – Summer', true, 'Spring', 'Slow', 'High', '{Well-draining,Sandy,Peaty}', 'Mediterranean Basin (southern France, Spain, North Africa)', 40, 15, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/272868185/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/272868185/medium.jpeg', true, 1455311, 210510, 'subspecies');
