INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera momoi', 'Monstera momoi', 6.0, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'All parts contain calcium oxalate crystals. Ingestion causes oral irritation, drooling, dysphagia, and gastrointestinal upset in cats and dogs.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings. Water thoroughly until drainage occurs, then allow drying interval before next application.', 60, 85, 'Intermediate', 'A rare and slow-growing tropical aroid with deeply lobed to fenestrated dark green leaves and trailing to climbing habit. Valued by collectors for its distinctive foliage pattern and compact growth compared to common Monstera species.', 'Indoor', true, true, 'Calcium oxalate crystals in stems and leaves cause oral burning, salivation, and throat irritation if chewed or ingested. Skin contact with sap may cause localized dermatitis in sensitive individuals.', false, NULL, true, 'Spring – Summer', 'Slow', 'Medium', '{Well-draining,Loamy,Rich}', 'Central America', 150, 90, true, NULL, NULL, true, 1639748, 1639748, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera mittermeieri', 'Monstera mittermeieri', 6.0, 7.5, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Sap contains calcium oxalate crystals; causes oral irritation, drooling, and difficulty swallowing in cats and dogs if ingested or chewed.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings; do not allow the entire rootball to dry out completely.', 60, 80, 'Intermediate', 'A rare tropical aroid closely related to Monstera deliciosa, distinguished by its smaller fenestrated leaves and compact growth habit. Prized by collectors for its unique foliage and air-purifying qualities; requires warm, humid conditions and bright, indirect light.', 'Indoor', true, true, 'Sap and leaves contain calcium oxalate crystals; ingestion causes oral pain, mouth irritation, and throat discomfort. Skin contact may cause mild dermatitis.', false, NULL, false, NULL, 'Moderate', 'Medium', '{Well-draining,Loamy,Rich}', 'Central America', 150, 100, true, NULL, NULL, true, 1639749, 1639749, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Smyrnium olusatrum', 'Alexanders', 6.0, 7.5, false, '{Seeds,Division}', true, NULL, '2026-06-08 01:14:33.368357+00', NULL, 'Average', '{full_sun,part_shade}', 'Biennial', NULL, 'Keep soil consistently moist during growing season; check soil at 2–3 cm depth and water when dry to touch. Reduce moisture in winter dormancy.', NULL, NULL, 'Beginner', 'A biennial Mediterranean herb with glossy, deeply lobed foliage and distinctive black seeds. All parts—leaves, stems, and roots—are edible with a celery-parsley flavour, historically cultivated as a potherb and culinary vegetable.', 'Outdoor', false, false, NULL, true, 'Summer', true, 'Late Spring – Early Summer', 'Moderate', 'Low', '{Well-draining,Loamy,Rich}', 'Mediterranean Basin', 120, 60, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/170421004/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/170421004/medium.jpg', true, 68007, 68007, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera tarrazuensis', 'Monstera tarrazuensis', 6.0, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Calcium oxalate crystals cause oral and throat irritation, drooling, and difficulty swallowing in cats and dogs. Ingestion may lead to vomiting.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings. Monsteras prefer slightly moist but not waterlogged soil.', 50, 80, 'Intermediate', 'A climbing aroid with deeply lobed, fenestrated leaves that mature with striking splits and holes. An air-purifying tropical houseplant prized for its architectural foliage and moderate vigor in indoor conditions.', 'Indoor', true, true, 'Calcium oxalate crystals cause burning and irritation of the mouth, lips, and throat if ingested. Sap may irritate skin on contact.', false, NULL, true, 'Spring – Summer', 'Moderate', 'Medium', '{Well-draining,Loamy,Rich}', 'Central America', 200, 100, true, NULL, NULL, true, 1387023, 1387023, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera xanthospatha', 'Monstera xanthospatha', 6.0, 7.5, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Contains calcium oxalate crystals; ingestion causes oral irritation, excessive drooling, and difficulty swallowing in cats and dogs.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings; check moisture at the soil surface before watering.', 60, 80, 'Intermediate', 'A tropical aroid with large, deeply lobed leaves and distinctive yellow-tinged spathes (hence the species name xanthospatha). Slower-growing than M. deliciosa but similarly attractive for indoor foliage displays and valued for air-purifying qualities.', 'Indoor', true, true, 'Calcium oxalate crystals cause oral and throat irritation if ingested; skin contact with sap may cause mild irritation.', false, NULL, true, 'Spring – Summer', 'Moderate', 'Medium', '{Well-draining,Loamy,Rich}', 'Central and South America', 150, 100, true, 'https://inaturalist-open-data.s3.amazonaws.com/photos/157182505/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/157182505/medium.jpeg', true, 639016, 639016, 'species');
