INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera planadensis', 'Monstera planadensis', 6.0, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Oxalate crystals in sap and leaves; ingestion causes oral irritation, drooling, and difficulty swallowing in cats and dogs.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings. Water when soil surface feels dry to touch.', 60, 80, 'Intermediate', 'A climbing aroid with deeply lobed or slightly fenestrated leaves and robust growth habit, valued for dramatic tropical foliage and air-purifying qualities in indoor settings.', 'Indoor', true, true, 'Oxalate crystals cause oral and throat irritation, burning, and swelling if plant material is ingested. Sap may irritate skin and eyes on contact.', false, NULL, false, NULL, 'Moderate', 'Medium', '{Well-draining,Loamy,Rich}', 'Central America and Mexico', 200, 90, true, 'https://inaturalist-open-data.s3.amazonaws.com/photos/219820974/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/219820974/medium.jpg', true, 952566, 952566, 'species');
