itat.', 'Outdoor', false, false, NULL, true, 'Late Summer – Autumn', true, 'Spring', 'Moderate', 'Low', '{Well-draining,Loamy,Rich}', 'Eastern North America (Nova Scotia to Georgia)', 900, 600, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/8048591/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/8048591/medium.jpg', true, 1466290, NULL, 'complex');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Abies pinsapo', 'Spanish fir', 6.0, 7.0, false, '{Seeds}', true, NULL, '2026-06-08 15:02:20.60003+00', NULL, 'Average', '{full_sun}', 'Perennial', NULL, 'Keep soil consistently moist but well-draining; check at 5 cm depth and water when the soil feels dry at this level.', 60, 75, 'Advanced', 'A slow-growing coniferous evergreen native to the mountains of southern Spain, featuring dense, dark green needle-like foliage and an elegant pyramidal form. Prized as an ornamental specimen tree and important for forestry and conservation efforts in its native habitat.', 'Outdoor', false, false, NULL, true, 'Autumn – Winter', false, NULL, 'Slow', 'High', '{Well-draining,Sandy,Loamy}', 'Sierra de Grazalema, southern Spain', 400, 200, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/108627343/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/108627343/medium.jpeg', true, 136896, 136896, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera alcirana', 'Monstera alcirana', 5.5, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Contains calcium oxalate crystals; causes oral irritation, drooling, and difficulty swallowing in cats and dogs if ingested.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings; check soil moisture at the surface before watering again.', 60, 80, 'Intermediate', 'A rare, slow-growing tropical aroid with deeply lobed, non-fenestrated leaves and an upright creeping habit. Prized by collectors for its unusual leaf morphology and compact growth pattern compared to common Monstera deliciosa.', 'Indoor', true, true, 'Sap and plant tissue contain calcium oxalate crystals; causes oral irritation, burning sensation, and potential swelling of mouth and throat if ingested. Skin contact may cause minor irritation.', false, NULL, true, 'Spring – Summer', 'Slow', 'Medium', '{Well-draining,Loamy,Rich}', 'Southeast Asia (endemic to Sulawesi, Indonesia)', 150, 90, true, 'https://inaturalist-open-data.s3.amazonaws.com/photos/105341547/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/105341547/medium.jpeg', true, 1160202, 1160202, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera tuberculata tuberculata', 'Monstera tuberculata tuberculata', 6.0, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Contains calcium oxalate crystals. Ingestion causes oral irritation, drooling, difficulty swallowing, and gastrointestinal upset in cats and dogs.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings. Water when the top inch feels dry to the touch.', 60, 85, 'Intermediate', 'A tropical climbing aroid with deeply lobed, textured leaves featuring distinctive tuberculate (bumpy) surface characteristics. A lesser-known Monstera species prized by collectors for its unusual foliage texture and moderate growth habit, ideal for moss poles and indirect bright environments.', 'Indoor', true, true, 'Contains calcium oxalate crystals. Ingestion causes burning and irritation of mouth, tongue, and throat; difficulty swallowing; and potential gastrointestinal distress. Skin contact may cause mild irritation.', false, NULL, false, NULL, 'Moderate', 'Medium', '{Well-draining,Rich,Moisture-retaining}', 'Central America', 200, 100, true, 'https://static.inaturalist.org/photos/653265979/square.jpg', 'https://static.inaturalist.org/photos/653265979/medium.jpg', true, 316457, 206269, 'variety');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera luteynii', 'Monstera luteynii', 6.0, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Insoluble calcium oxalate crystals cause oral and throat irritation, drooling, and swallowing difficulties in cats and dogs if ingested.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings. Check soil moisture at the surface before watering.', 60, 80, 'Intermediate', 'A rare aroid species with deeply lobed or fenestrated foliage and a compact growth habit compared to Monstera deliciosa. Prized by collectors for its distinctive leaf architecture and moderate size, making it suitable for indoor display.', 'Indoor', true, true, 'Insoluble calcium oxalate crystals cause mouth and throat burning, difficulty swallowing, and mild gastric upset if leaves or stems are ingested.', false, NULL, false, NULL, 'Slow', 'Medium', '{Well-draining,Loamy,Rich}', 'Central and South America', 150, 120, true, 'https://inaturalist-open-data.s3.amazonaws.com/photos/513702068/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/513702068/medium.jpg', true, 952580, 952580, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Kolkwitzia amabilis', 'Beauty bush', 6.0, 7.5, false, '{"Stem Cuttings",Seeds}', true, NULL, '2026-06-08 03:39:40.778285+00', NULL, 'Average', '{full_sun,part_shade}', 'Perennial', NULL, 'Check soil 2–3 cm deep; water when dry to touch. Prefers moderate moisture during growing season but is drought-tolerant once established.', NULL, NULL, 'Beginner', 'A deciduous temperate shrub with arching branches and abundant pink tubular flowers in late spring, valued for its ornamental appeal and hardy constitution in mixed borders and hedgerows.', 'Outdoor', false, false, NULL, true, 'Late Summer – Autumn', true, 'Late Spring – Early Summer', 'Moderate', 'Low', '{Well-draining,Loamy}', 'Central China', 210, 240, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/44278471/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/44278471/medium.jpg', true, 52501, 52501, 'species');
