INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Nemesia silvatica', 'White forest lionface', 6.0, 7.0, false, '{Seeds,"Stem Cuttings"}', true, NULL, '2026-06-08 03:42:32.037174+00', NULL, 'Average', '{full_sun,part_shade}', 'Annual', NULL, 'Allow top 1–2 cm of soil to dry between waterings; keep consistently moist during growing season but avoid waterlogging.', 40, 60, 'Beginner', 'A delicate annual wildflower native to South African forests, producing charming white snapdragon-like blooms with distinctive spotted throats. Prized for cottage gardens and mixed borders for its long flowering season and attract pollinators.', 'Outdoor', false, false, NULL, false, NULL, true, 'Spring – Summer', 'Moderate', 'Low', '{Well-draining,Loamy}', 'South Africa, temperate forest regions', 30, 20, false, 'https://static.inaturalist.org/photos/196478866/square.jpeg', 'https://static.inaturalist.org/photos/196478866/medium.jpeg', true, 590498, 590498, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Bersama tysoniana', 'Coast bersama', 6.0, 7.5, false, '{Seeds,"Stem Cuttings"}', true, NULL, '2026-06-08 03:42:32.037174+00', NULL, 'Average', '{full_sun,part_shade}', 'Perennial', NULL, 'Allow top 3–5 cm of soil to dry between waterings during the growing season; reduce watering in dormancy.', 40, 65, 'Intermediate', 'A semi-deciduous to evergreen tree native to coastal regions of southern Africa, characterised by pinnate foliage and small clustered flowers followed by distinctive bright red seed capsules. Valued for its ornamental appeal, wildlife habitat support, and adaptation to warm, well-drained conditions.', 'Outdoor', false, false, NULL, true, 'Autumn – Winter', true, 'Spring – Summer', 'Moderate', 'Low', '{Well-draining,Sandy,Loamy}', 'Coastal southern Africa (South Africa, Mozambique)', 800, 600, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/31327437/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/31327437/medium.jpg', true, 581117, 581117, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera integrifolia', 'Monstera integrifolia', 6.0, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Sap and leaves contain calcium oxalate crystals, causing oral irritation, drooling, and difficulty swallowing in cats and dogs if ingested.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings; check at the surface. Water when dry at the touch.', 60, 80, 'Intermediate', 'A tropical aroid with deeply lobed, non-fenestrated leaves and vigorous climbing or trailing habit. Prized for distinctive foliage and air-purifying qualities in intermediate to advanced indoor cultivation.', 'Indoor', true, true, 'Sap and leaves contain calcium oxalate crystals, causing oral irritation, burning sensation in the mouth and throat if ingested. Skin contact may cause dermatitis.', false, NULL, true, 'Spring – Summer', 'Moderate', 'Medium', '{Well-draining,Loamy,Rich}', 'Central and South America', 200, 80, true, 'https://static.inaturalist.org/photos/336200960/square.jpg', 'https://static.inaturalist.org/photos/336200960/medium.jpg', true, 952592, 952592, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera gigas', 'Monstera gigas', 6.0, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Insoluble calcium oxalate crystals cause oral irritation, drooling, and difficulty swallowing in cats and dogs if ingested.', 'Average', '{filtered_indirect}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings; do not allow the plant to sit in standing water.', 60, 80, 'Intermediate', 'A large climbing aroid with massive, deeply fenestrated leaves and thick stems, prized for dramatic foliage and architectural presence in indoor tropical environments. Fast-growing and air-purifying, though requiring consistent warmth and humidity.', 'Indoor', true, true, 'Insoluble calcium oxalate crystals cause burning and irritation of mouth, throat, and digestive tract if ingested. Sap may irritate skin.', false, NULL, true, 'Spring – Summer', 'Fast', 'Medium', '{Well-draining,Loamy,Rich}', 'Central and South America (tropical rainforests)', 300, 200, true, 'https://inaturalist-open-data.s3.amazonaws.com/photos/178852883/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/178852883/medium.jpeg', true, 1472966, 1472966, 'species');
