INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Liatris × freemaniana', 'Liatris × freemaniana', 6.0, 7.5, false, '{Division,Seeds}', true, NULL, '2026-06-08 03:45:16.290036+00', NULL, 'Average', '{full_sun}', 'Perennial', NULL, 'Check soil 5 cm deep; allow top layer to dry between waterings once established.', NULL, NULL, 'Beginner', 'A hybrid herbaceous perennial with tall spikes of magenta-pink to purple flowers blooming from mid to late summer. Hardy, drought-tolerant once established, and attractive to pollinators, making it a reliable garden specimen for borders and native plantings.', 'Outdoor', false, false, NULL, false, NULL, true, 'Mid Summer – Late Summer', 'Moderate', 'Low', '{Well-draining,Sandy,Loamy}', 'Hybrid origin (derived from Liatris spicata and Liatris microstachya, North American natives)', 90, 45, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/319901746/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/319901746/medium.jpeg', true, 170843, 170843, 'hybrid');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera kikiae', 'Monstera kikiae', 6.0, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Contains calcium oxalate crystals; ingestion causes oral irritation, drooling, and difficulty swallowing in cats and dogs.', 'Average', '{filtered_indirect}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings. Check soil moisture at the surface; water when dry to touch.', 60, 80, 'Intermediate', 'A rare climbing or vining Monstera species with deeply lobed, smaller leaves than M. deliciosa, prized by collectors for its distinctive foliage and compact growth habit. Excellent as an indoor tropical plant for bright, humid environments.', 'Indoor', true, true, 'Sap and fruit contain calcium oxalate crystals; ingestion causes mouth and throat irritation, swallowing difficulty, and gastric upset. Skin contact may cause mild irritation.', true, 'Late Summer – Autumn', true, 'Summer', 'Moderate', 'Medium', '{Well-draining,Loamy,Rich,Moisture-retaining}', 'Borneo and Southeast Asia', 200, 60, true, 'https://inaturalist-open-data.s3.amazonaws.com/photos/152984924/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/152984924/medium.jpg', true, 1548096, 1548096, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera guzmanjacobiae', 'Monstera guzmanjacobiae', 6.0, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Contains calcium oxalate crystals. Ingestion causes oral irritation, drooling, and difficulty swallowing in cats and dogs. Skin contact may cause dermatitis.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings. Check soil moisture at surface before watering.', 60, 85, 'Intermediate', 'A rare tropical aroid with deeply lobed or fenestrated leaves and distinctive climbing or trailing growth habit. Valued for dramatic foliage and compact size compared to common Monstera species.', 'Indoor', true, true, 'Calcium oxalate crystals in leaves and stems cause oral irritation and burning sensation if ingested. Skin contact may trigger mild dermatitis.', false, NULL, false, NULL, 'Moderate', 'Medium', '{Well-draining,Rich,Moisture-retaining}', 'Central America', 150, 120, true, 'https://inaturalist-open-data.s3.amazonaws.com/photos/119076308/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/119076308/medium.jpeg', true, 1203794, 1203794, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Rhinerrhiza divitiflora', 'Raspy root orchid', 5.5, 6.5, false, '{Division}', true, NULL, '2026-06-08 03:45:16.290036+00', NULL, 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow potting medium surface to dry between waterings; check at surface level. This epiphytic orchid requires excellent drainage and should never remain waterlogged.', 60, 80, 'Advanced', 'A rare epiphytic orchid from northeastern Australia with characteristic rough, papery roots and inconspicuous pale yellow flowers. Highly specialised for humid tropical forest conditions and demanding of precise growing environments.', 'Indoor', true, false, NULL, false, NULL, true, 'Spring – Summer', 'Slow', 'High', '{Well-draining,Peaty}', 'Tropical northeastern Australia (Queensland)', 20, 15, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/162996667/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/162996667/medium.jpeg', true, 534402, 534402, 'species');
