INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Scapania cuspiduligera', 'Untidy earwort', 5.0, 7.0, false, '{Division}', true, NULL, '2026-06-08 03:45:49.588414+00', NULL, 'Frequent', '{part_shade,full_shade}', 'Perennial', NULL, 'Keep substrate consistently moist; this liverwort requires high moisture levels and should never fully dry out.', 85, 100, 'Advanced', 'A small, creeping liverwort with distinctive two-lobed leaves arranged in an untidy rosette pattern. Scapania cuspiduligera is a bryophyte requiring constant moisture and shade, primarily of interest to specialists and moss terrarium enthusiasts.', 'Indoor', false, false, NULL, false, NULL, false, NULL, 'Slow', 'High', '{Peaty,Moisture-retaining}', 'Northern temperate regions, particularly cool boreal forests and mountain habitats', 2, 15, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/540397006/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/540397006/medium.jpg', true, 168500, 168500, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Haworthiopsis attenuata', 'Zebra haworthia', 6.0, 7.5, false, '{"Leaf Cuttings","Offset Separation"}', true, NULL, '2026-06-08 01:14:33.679222+00', NULL, 'Minimum', '{full_sun,part_shade}', 'Perennial', NULL, 'Let soil dry completely between waterings. Check soil 1–2 cm deep; water only when bone-dry.', 30, 50, 'Beginner', 'A compact succulent with distinctive white-banded rosettes, forming dense clumps. Prized for its drought tolerance and architectural appeal in rock gardens and container collections.', 'Both', false, false, NULL, false, NULL, true, 'Summer', 'Slow', 'Low', '{Well-draining,Sandy}', 'South Africa (Eastern Cape)', 15, 20, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/19240639/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/19240639/medium.jpg', true, 577654, 577654, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Rubus acerispinus', 'Rubus acerispinus', 5.5, 7.0, false, '{Division,Seeds}', true, NULL, '2026-06-08 03:45:49.588414+00', NULL, 'Average', '{full_sun,part_shade}', 'Perennial', NULL, 'Allow soil to dry slightly between waterings; check at 2–3 cm depth. Prefer moist but well-draining conditions.', NULL, NULL, 'Intermediate', 'A deciduous bramble species with deeply lobed, maple-like leaves and thorny stems, producing small red to black fruits. Native to temperate regions, it is valued for wildlife habitat and occasional fruit production.', 'Outdoor', false, false, NULL, true, 'Late Summer – Autumn', true, 'Late Spring – Early Summer', 'Moderate', 'Low', '{Well-draining,Loamy,Sandy}', 'Temperate North America', 200, 150, false, NULL, NULL, true, 1446052, 1446052, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera coclensis', 'Monstera coclensis', 6.0, 7.5, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Contains calcium oxalate crystals; ingestion causes oral irritation, drooling, and difficulty swallowing in cats and dogs.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings; water when soil moisture recedes from the pot edge.', 60, 80, 'Intermediate', 'A tropical climbing aroid with deeply lobed leaves and rare fenestration, similar to its Monstera deliciosa relatives but with more compact and refined foliage. Prized for dramatic vining growth in humid indoor conditions and moderate air-purifying qualities.', 'Indoor', true, true, 'Ingestion of leaves or stems causes oral and throat irritation, burning sensation, and potential swelling. Sap may cause skin irritation in sensitive individuals.', false, NULL, true, 'Spring – Summer', 'Moderate', 'Medium', '{Well-draining,Loamy,Rich}', 'Central and South America (Ecuador, Colombia)', 180, 120, true, NULL, NULL, true, 1639754, 1639754, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Acer', 'Maples', 6.0, 7.5, false, '{Seeds,"Stem Cuttings"}', true, NULL, '2026-06-08 03:45:49.588414+00', NULL, 'Average', '{full_sun,part_shade}', 'Perennial', NULL, 'Check soil moisture 5–7 cm deep; water when soil feels dry at this depth. Maples prefer consistently moist but not waterlogged soil during the growing season.', NULL, NULL, 'Beginner', 'A diverse genus of deciduous and evergreen trees and shrubs renowned for striking foliage and vibrant autumn colour. Maples range from delicate Japanese specimens to large shade trees, offering ornamental value and ecological importance across temperate regions.', 'Outdoor', false, false, NULL, true, 'Summer – Autumn', true, 'Spring', 'Moderate', 'Low', '{Well-draining,Loamy,Rich}', 'Northern Hemisphere temperate regions including Asia, Europe, and North America', 3000, 2000, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/99147747/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/99147747/medium.jpg', true, 47727, NULL, 'genus');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Euphorbia acerensis', 'Euphorbia acerensis', 6.0, 7.5, true, '{"Stem Cuttings",Seeds}', true, NULL, '2026-06-08 03:45:49.588414+00', 'Sap contains irritant diterpenes; causes dermatitis on contact and gastrointestinal upset if ingested by dogs and cats.', 'Minimum', '{full_sun,part_shade}', 'Perennial', NULL, 'Allow soil to dry completely between waterings. Check at soil depth of 3–5 cm; water only when entirely dry.', 30, 50, 'Intermediate', 'A spiny, succulent euphorb native to arid regions, distinguished by fine, needle-like foliage and compact, cushion-like growth. Valued in xeriscaping and alpine collections for drought tolerance and architectural form.', 'Outdoor', false, true, 'Sap causes skin and eye irritation on contact. Ingestion of stem tissue causes severe gastric distress, nausea, and potential dermatitis of mucous membranes.', true, 'Spring – Summer', true, 'Spring', 'Slow', 'Low', '{Well-draining,Sandy,Poor}', 'Morocco (Atlas Mountains)', 30, 40, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/119890507/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/119890507/medium.jpeg', true, 1068409, 1068409, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Prunus lusitanica', 'Portuguese laurel', 6.0, 7.5, true, '{"Stem Cuttings",Seeds}', true, NULL, '2026-06-08 03:45:49.588414+00', 'All parts contain cyanogenic glycosides. Ingestion of leaves, seeds, or bark may cause cyanide poisoning in pets and humans. Symptoms include respiratory distress, dilated pupils, and gastrointestinal upset.', 'Average', '{full_sun,part_shade}', 'Perennial', NULL, 'Check soil 2–3 cm deep. Water when surface feels dry to touch, but do not allow prolonged waterlogging.', 40, 60, 'Beginner', 'A slow-growing evergreen shrub or small tree with glossy, dark green foliage and small fragrant white flowers followed by deep purple-black berries. Hardy and widely cultivated as a formal hedge or specimen plant in temperate climates.', 'Outdoor', false, true, 'All parts contain cyanogenic glycosides. Ingestion of leaves, seeds, or bark may cause cyanide poisoning. Symptoms include respiratory distress, dilated pupils, nausea, vomiting, and abdominal pain.', true, 'Autumn – Winter', true, 'Spring – Early Summer', 'Slow', 'Low', '{Well-draining,Loamy,Rich}', 'Iberian Peninsula and Morocco', 600, 400, false, 'https://static.inaturalist.org/photos/428364516/square.jpeg', 'https://static.inaturalist.org/photos/428364516/medium.jpeg', true, 127529, 127529, 'species');
