INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera gentryi', 'Monstera gentryi', 6.0, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Contains calcium oxalate crystals; ingestion causes oral irritation, drooling, and difficulty swallowing in cats and dogs.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings. Do not allow the entire root ball to dry out completely.', 60, 80, 'Intermediate', 'A rare Monstera species with moderately-sized fenestrated leaves and slower growth than M. deliciosa, valued by collectors for its distinctive foliage and compact habit. Requires warm, humid conditions and indirect light.', 'Indoor', true, true, 'Calcium oxalate raphides cause mouth and throat irritation, swelling of lips and tongue, and difficulty swallowing if ingested. Skin contact with sap may cause mild irritation.', true, 'Summer – Autumn', true, 'Spring – Summer', 'Slow', 'Medium', '{Well-draining,Loamy,Rich}', 'Central America (Guatemala, Honduras)', 150, 100, true, NULL, NULL, true, 1548100, 1548100, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera', 'Monstera', 6.0, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Contains calcium oxalate crystals; ingestion causes oral irritation, drooling, and difficulty swallowing in cats and dogs.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings. Do not let the plant sit in waterlogged soil.', 50, 80, 'Beginner', 'A vigorous tropical aroid with large, heart-shaped leaves that develop characteristic fenestrations (holes) as the plant matures. Prized for dramatic foliage and air-purifying qualities, it is exceptionally tolerant of indoor conditions and low light.', 'Indoor', true, true, 'Sap and leaves contain calcium oxalate crystals; ingestion causes oral and throat irritation, difficulty swallowing, and mild gastrointestinal upset. Sap may cause skin irritation in sensitive individuals.', true, 'Spring – Summer', true, 'Spring – Summer', 'Fast', 'Low', '{Well-draining,Loamy,Rich}', 'Central and South America (Mexico to Panama)', 200, 100, true, 'https://inaturalist-open-data.s3.amazonaws.com/photos/23676736/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/23676736/medium.jpeg', true, 122522, NULL, 'genus');
