INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera praetermissa', 'Monstera praetermissa', 6.0, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Contains calcium oxalate crystals; ingestion causes oral irritation, drooling, and difficulty swallowing in cats and dogs.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings; water when the surface feels dry to the touch.', 60, 85, 'Intermediate', 'A rare tropical aroid with deeply fenestrated, heart-shaped leaves and climbing or creeping habit, similar to Monstera deliciosa but smaller and more delicate. Prized by collectors for its distinctive foliage and air-purifying qualities; well-suited to indoor cultivation.', 'Indoor', true, true, 'Calcium oxalate crystals present; ingestion causes oral irritation, mouth pain, and potential difficulty swallowing. Sap may irritate skin and eyes on contact.', false, NULL, true, 'Spring – Summer', 'Moderate', 'Medium', '{Well-draining,Loamy,Rich}', 'Central America (Mexico and Guatemala)', 180, 90, true, 'https://inaturalist-open-data.s3.amazonaws.com/photos/177688155/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/177688155/medium.jpeg', true, 947103, 947103, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera panamensis', 'Monstera panamensis', 6.0, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Contains calcium oxalate crystals. Ingestion causes oral irritation, difficulty swallowing, and gastrointestinal upset in cats and dogs.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings. Monsteras prefer consistent moisture but not waterlogging.', 60, 80, 'Intermediate', 'A tropical aroid with deeply lobed to fenestrated leaves and a climbing or trailing habit. Prized as a foliage houseplant for its architectural form and moderate air-purifying properties.', 'Indoor', true, true, 'Sap and leaves contain calcium oxalate crystals. Ingestion causes oral and throat irritation, burning sensation, and potential difficulty swallowing. Skin contact may cause dermatitis in sensitive individuals.', false, NULL, true, 'Spring – Summer', 'Moderate', 'Medium', '{Well-draining,Loamy,Rich}', 'Central and South America (Panama, Colombia, Ecuador)', 200, 60, true, 'https://static.inaturalist.org/photos/335583847/square.jpg', 'https://static.inaturalist.org/photos/335583847/medium.jpg', true, 1544462, 1544462, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera cenepensis', 'Monstera cenepensis', 6.0, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Calcium oxalate crystals cause oral irritation, drooling, and difficulty swallowing in cats and dogs if ingested.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings. Check at the surface before watering; soil should feel slightly moist but not waterlogged.', 60, 85, 'Intermediate', 'A tropical aroid with deeply lobed, semi-fenestrated foliage and climbing or vining growth habit. Prized for its distinctive architectural leaves and adaptability to indoor conditions; slower-growing than Monstera deliciosa.', 'Indoor', true, true, 'Calcium oxalate crystals cause oral and throat irritation if ingested. Sap may irritate sensitive skin and eyes on contact.', false, NULL, false, NULL, 'Moderate', 'Medium', '{Well-draining,Rich,Loamy}', 'Central America (endemic to Ecuador and Peru cloud forests)', 180, 120, true, NULL, NULL, true, 952571, 952571, 'species');
