INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera tacanaensis', 'Monstera tacanaensis', 6.0, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Contains calcium oxalate crystals. Ingestion causes oral irritation, difficulty swallowing, and gastrointestinal upset in cats and dogs.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings. Water when soil is dry at this depth; do not allow the root ball to dry completely.', 60, 80, 'Intermediate', 'A rare tropical aroid with deeply lobed or fenestrated leaves, similar to Monstera deliciosa but more compact and slower-growing. Prized by collectors for its unique foliage and adaptability to indoor cultivation.', 'Indoor', true, true, 'Contains calcium oxalate crystals. Ingestion causes mouth and throat irritation, difficulty swallowing, and gastrointestinal discomfort. Sap may irritate skin and eyes on contact.', false, NULL, true, 'Spring – Summer', 'Slow', 'Medium', '{Well-draining,Loamy,Rich}', 'Central America (Belize, Guatemala)', 150, 90, true, 'https://inaturalist-open-data.s3.amazonaws.com/photos/189349234/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/189349234/medium.jpeg', true, 1377201, 1377201, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera anomala', 'Monstera anomala', 6.0, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Sap contains calcium oxalate crystals; ingestion causes oral irritation, drooling, and difficulty swallowing in cats and dogs.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings; do not allow to dry completely.', 60, 80, 'Intermediate', 'A tropical aroid closely related to Monstera deliciosa, characterized by large, deeply lobed or pinnatifid foliage with potential fenestration. Prized as a houseplant for its dramatic, sculptural leaves and moderate air-purifying capacity.', 'Indoor', true, true, 'Ingestion of leaves or stems causes oral pain, burning, and swelling of the mouth and throat due to calcium oxalate crystals.', false, NULL, false, NULL, 'Moderate', 'Medium', '{Well-draining,Loamy,Rich}', 'Central America', 200, 120, true, 'https://inaturalist-open-data.s3.amazonaws.com/photos/296051301/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/296051301/medium.jpeg', true, 952590, 952590, 'species');
