INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera donosoensis', 'Monstera donosoensis', 6.0, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Contains insoluble calcium oxalate crystals. Ingestion causes oral irritation, drooling, dysphagia, and gastrointestinal upset in cats and dogs.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings. Keep evenly moist during growing season but avoid waterlogging.', 60, 80, 'Intermediate', 'A rare tropical aroid with deeply lobed or slightly fenestrated dark green foliage, resembling a smaller relative of Monstera deliciosa. Valued by collectors for its compact growth habit and distinctive leaf morphology, though less commonly cultivated than its popular cousin.', 'Indoor', true, true, 'Insoluble calcium oxalate crystals cause burning and swelling of lips, mouth, and throat if ingested. Skin contact may cause mild irritation.', false, NULL, true, 'Spring – Summer', 'Moderate', 'Medium', '{Well-draining,Loamy,Rich}', 'Costa Rica', 150, 90, true, 'https://inaturalist-open-data.s3.amazonaws.com/photos/234572560/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/234572560/medium.jpeg', true, 1510351, 1510351, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera amargalensis', 'Monstera amargalensis', 6.0, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Contains calcium oxalate crystals; ingestion causes oral irritation, difficulty swallowing, and gastrointestinal upset in cats and dogs.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings; check at this depth before watering again.', 65, 85, 'Intermediate', 'A tropical aroid endemic to Queensland, Australia, characterised by large fenestrated leaves and climbing or trailing growth habit. Prized by collectors for its rarity and distinctive foliage, suitable for bright indoor cultivation.', 'Indoor', true, true, 'Calcium oxalate raphides cause oral and throat irritation, burning sensation, and potential oedema if ingested. Sap may irritate skin and eyes on contact.', true, 'Summer – Autumn', true, 'Spring – Summer', 'Moderate', 'Medium', '{Well-draining,Loamy,Rich}', 'Tropical rainforests of Queensland, Australia', 200, 100, false, NULL, NULL, true, 952565, 952565, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera gambensis', 'Monstera gambensis', 6.0, 7.5, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Contains calcium oxalate crystals. Ingestion causes oral irritation, drooling, difficulty swallowing, and potential airway swelling in pets. Skin contact may cause dermatitis.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings. Water thoroughly when soil feels dry at this depth. Avoid waterlogging, as roots are susceptible to rot.', 60, 85, 'Intermediate', 'A rare aroid from West Africa with deeply lobed and fenestrated leaves, similar to its better-known cousin Monstera deliciosa. Grown primarily for its dramatic, sculptural foliage and slow to moderate growth habit.', 'Indoor', true, true, 'Contains calcium oxalate crystals. Ingestion causes oral irritation, burning sensation in the mouth and throat, and gastrointestinal upset. Skin contact may cause localized irritation.', false, NULL, false, NULL, 'Moderate', 'Medium', '{Well-draining,Loamy,Rich}', 'West Africa (Cameroon, Nigeria)', 180, 90, false, NULL, NULL, true, 1639752, 1639752, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Chamaecyparis thyoides ''Red Star''', 'Red star whitecedar', 5.0, 6.5, false, '{"Stem Cuttings",Seeds}', true, '{"id": 229, "genus": "Chamaecyparis", "family": "Cupressaceae", "hybrid": null, "variety": null, "cultivar": "Red Star", "authority": null, "other_name": ["Whitecedar Falsecypress", "Atlantic White Cedar"], "subspecies": null, "common_name": "Red Star Whitecedar", "default_image": null, "scientific_name": ["Chamaecyparis thyoides ''Red Star''"], "species_epithet": "thyoides"}', '2026-06-06 07:12:14.191321+00', NULL, 'Average', '{full_sun,part_shade}', 'Perennial', NULL, 'Allow top 5 cm of soil to dry between waterings; keep consistently moist but not waterlogged, particularly during establishment and growing season.', NULL, NULL, 'Intermediate', 'A compact evergreen conifer cultivar of Atlantic whitecedar with distinctive reddish-bronze foliage, particularly intense in winter. Valued for year-round ornamental color, fine texture, and suitability to moist, poorly drained sites in temperate landscapes.', 'Outdoor', false, false, NULL, false, NULL, false, NULL, 'Slow', 'Low', '{Well-draining,Loamy,Peaty,Moisture-retaining}', 'Eastern North America (Atlantic coastal wetlands and swamps)', 150, 90, false, 'https://static.inaturalist.org/photos/526545/square.jpg', 'https://static.inaturalist.org