, 'Autumn', true, 'Winter – Early Spring', 'Moderate', 'Low', '{}', 'Eastern North America', 600, 400, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/2261216/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/2261216/medium.jpg', true, 56033, 56033, 'species');
