INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Soldanella montana', 'Mountain tassel-flower', 6.0, 7.5, false, '{Seeds,Division}', true, NULL, '2026-06-08 15:02:20.60003+00', NULL, 'Frequent', '{part_shade,filtered_indirect}', 'Perennial', NULL, 'Keep soil consistently moist but not waterlogged; check at surface and water when top 1 cm begins to dry.', 60, 80, 'Intermediate', 'A delicate alpine perennial with charming nodding, fringed bell-shaped flowers in purple or lavender, native to mountain meadows and rocky slopes. Prized by alpine garden enthusiasts for its compact habit and distinctive tassel-like blooms.', 'Outdoor', false, false, NULL, false, NULL, true, 'Spring – Early Summer', 'Slow', 'Medium', '{}', 'European Alps and mountains of Central Europe', 15, 20, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/2580780/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/2580780/medium.jpg', true, 169090, 169090, 'species');
