INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Ophrys fusca fusca', 'Brown bee orchid', 6.0, 7.5, false, '{Division,Seeds}', true, NULL, '2026-06-08 15:02:20.60003+00', NULL, 'Minimum', '{full_sun,part_shade}', 'Perennial', NULL, 'Allow substrate to dry between waterings. Check at surface; water only when top 1–2 cm is dry. Avoid waterlogging during dormancy.', 40, 60, 'Advanced', 'A Mediterranean terrestrial orchid with distinctive dark brown, velvety flowers that mimic female bees to facilitate pollination. Highly specialized and challenging in cultivation, requiring precise dormancy cycles and well-drained terrestrial orchid substrate.', 'Outdoor', false, false, NULL, true, 'Late Spring – Early Summer', true, 'Spring', 'Slow', 'High', '{Well-draining,Sandy,Peaty}', 'Mediterranean Basin (Southern Europe, North Africa)', 30, 15, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/204889263/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/204889263/medium.jpeg', true, 210512, 210510, 'subspecies');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Hylotelephium', 'Live-forever', 6.0, 7.5, false, '{"Leaf Cuttings","Stem Cuttings",Division,"Offset Separation"}', true, NULL, '2026-06-08 14:53:26.005375+00', NULL, 'Minimum', '{full_sun,part_shade}', 'Perennial', NULL, 'Allow soil to dry completely between waterings. Check soil 2–3 cm deep; water only when entirely dry.', NULL, NULL, 'Beginner', 'A hardy, drought-tolerant succulent perennial with fleshy leaves and dense flower clusters in shades of pink, red, or white. Prized for low maintenance, seasonal color, and bee-attracting blooms in late summer to autumn.', 'Both', false, false, NULL, false, NULL, true, 'Late Summer – Autumn', 'Moderate', 'Low', '{Well-draining,Sandy,Poor}', 'Northern Hemisphere temperate regions, including Europe and Asia', 60, 60, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/119448388/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/119448388/medium.jpg', true, 84036, NULL, 'genus');
