INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera adansonii', 'Swiss cheese-plant', 6.0, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'Contains calcium oxalate crystals; ingestion causes oral irritation, drooling, and difficulty swallowing in cats and dogs.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings. Check soil moisture at the surface; avoid waterlogging.', 50, 80, 'Beginner', 'A trailing tropical aroid with small, heart-shaped leaves featuring distinctive perforations and fenestration as the plant matures. Highly adaptable, fast-growing, and excellent for hanging baskets or as a climbing vine on moss poles indoors.', 'Indoor', true, true, 'Contains calcium oxalate crystals; ingestion causes oral irritation, throat burning, and difficulty swallowing. Sap may irritate skin and eyes on contact.', false, NULL, true, 'Spring – Summer', 'Fast', 'Low', '{Well-draining,Loamy,Rich}', 'Central and South America, West Indies', 200, 60, true, 'https://inaturalist-open-data.s3.amazonaws.com/photos/451925925/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/451925925/medium.jpeg', true, 206267, 206267, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera adansonii laniata', 'Monstera adansonii laniata', 6.0, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-08 03:51:39.681918+00', 'All parts contain calcium oxalate crystals; ingestion causes oral irritation, drooling, and difficulty swallowing in cats and dogs.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings; do not let the plant sit in standing water.', 60, 80, 'Intermediate', 'A vining aroid with deeply lobed, leathery leaves and prominent fenestration patterns. This cultivar is prized for its distinctive textured foliage and air-purifying qualities, thriving in warm, humid indoor environments.', 'Indoor', true, true, 'Calcium oxalate crystals cause mouth and throat irritation if ingested; sap may irritate skin and eyes upon contact.', false, NULL, false, NULL, 'Moderate', 'Medium', '{Well-draining,Loamy,Rich}', 'Central and South America', 180, 60, true, 'https://inaturalist-open-data.s3.amazonaws.com/photos/600795270/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/600795270/medium.jpg', true, 243718, 206267, 'subspecies');
