INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Myosotis scorpioides', 'Water forget-me-not', 6.0, 7.5, false, '{Seeds,Division}', true, NULL, '2026-06-08 14:53:26.005375+00', NULL, 'Frequent', '{part_shade,filtered_indirect}', 'Perennial', NULL, 'Keep soil consistently moist to wet; check soil moisture at the surface and maintain waterlogged or marshy conditions. Allow no drying between waterings.', NULL, NULL, 'Beginner', 'A low-growing perennial marsh plant with delicate blue flowers and narrow green leaves, valued for wetland gardens, pond edges, and water features. Thrives in consistently wet conditions and produces prolific soft blue blooms throughout the growing season.', 'Outdoor', false, false, NULL, false, NULL, true, 'Late Spring – Summer', 'Moderate', 'Low', '{Loamy,Peaty,Moisture-retaining}', 'Europe, Western Asia', 30, 40, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/199155526/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/199155526/medium.jpg', true, 49130, 49130, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Liquidambar styraciflua', 'American sweetgum', 5.5, 7.5, false, '{Seeds,"Stem Cuttings"}', true, NULL, '2026-06-08 04:16:08.171272+00', NULL, 'Average', '{full_sun,part_shade}', 'Perennial', NULL, 'Allow top 5 cm of soil to dry between waterings during establishment; mature trees are drought-tolerant once established.', NULL, NULL, 'Beginner', 'A large deciduous tree native to eastern North America with distinctive five- to seven-lobed star-shaped leaves that display brilliant crimson, orange, and purple autumn foliage. Produces characteristic spiky spherical seed capsules and is valued for timber, ornamental appeal, and air-purifying qualities.', 'Outdoor', false, false, NULL, true, 'Autumn – Winter', true, 'Spring – Early Summer', 'Moderate', 'Low', '{Well-draining,Loamy,Moisture-retaining}', 'Eastern and southeastern United States', 2100, 1200, true, 'https://inaturalist-open-data.s3.amazonaws.com/photos/239888168/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/239888168/medium.jpeg', true, 49658, 49658, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Aquilegia formosa', 'Western columbine', 6.0, 7.5, true, '{Seeds,Division}', true, NULL, '2026-06-08 14:53:26.005375+00', 'All parts contain cardiogenic toxins and irritant compounds. Ingestion may cause gastrointestinal upset, dermatitis on contact with sap.', 'Average', '{part_shade,filtered_indirect}', 'Perennial', NULL, 'Keep soil evenly moist during growing season; allow surface to dry slightly between waterings. Reduce watering in dormancy.', 40, 60, 'Intermediate', 'A charming native perennial with distinctive red and yellow spurred flowers and delicate blue-green foliage, widely cultivated in woodland gardens and shade borders for its elegant, nodding blooms and hummingbird attraction.', 'Outdoor', false, true, 'Foliage and roots contain ranunculin, a toxic irritant compound. Skin contact may cause dermatitis; ingestion causes gastrointestinal upset and burning sensation in the mouth.', true, 'Summer – Early Autumn', true, 'Late Spring – Early Summer', 'Moderate', 'Medium', '{Well-draining,Loamy,Rich}', 'Western North America (Pacific Coast from British Columbia to Baja California)', 90, 45, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/534432091/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/534432091/medium.jpg', true, 48244, 48244, 'species');
