INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Delonix regia', 'Flamboyant', 6.0, 7.5, false, '{Seeds}', true, NULL, '2026-06-08 14:53:26.005375+00', NULL, 'Average', '{full_sun}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings during growing season. Reduce watering significantly in winter dormancy.', 40, 70, 'Intermediate', 'A deciduous tropical tree with feathery bipinnate foliage and spectacular scarlet-orange flowers with crimped petals, prized for dramatic ornamental impact in warm climates and as a street tree throughout the tropics.', 'Outdoor', true, false, NULL, true, 'Late Summer – Autumn', true, 'Late Spring – Summer', 'Fast', 'Medium', '{Well-draining,Loamy}', 'Madagascar', 1200, 800, false, 'https://static.inaturalist.org/photos/138221563/square.jpg', 'https://static.inaturalist.org/photos/138221563/medium.jpg', true, 62839, 62839, 'species');
