INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Cichorium intybus', 'Chicory', 6.0, 7.5, false, '{Seeds,Division}', true, NULL, '2026-06-08 04:17:54.354107+00', NULL, 'Average', '{full_sun,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings; chicory prefers moderate moisture but tolerates drought once established.', NULL, NULL, 'Beginner', 'A hardy herbaceous perennial with slender stems, narrow leaves, and striking sky-blue flowers; widely cultivated for its edible roots (used as a coffee substitute) and bitter greens, valued for both culinary and ornamental purposes.', 'Outdoor', false, false, NULL, true, 'Summer – Autumn', true, 'Summer – Early Autumn', 'Moderate', 'Low', '{Well-draining,Loamy,Sandy}', 'Mediterranean Basin and Western Asia', 100, 45, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/283894255/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/283894255/medium.jpg', true, 52913, 52913, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Cichorium intybus spicatum', 'Cichorium intybus spicatum', 6.0, 7.5, false, '{Seeds,Division}', true, NULL, '2026-06-08 04:17:54.354107+00', NULL, 'Minimum', '{full_sun}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings; established plants are drought-tolerant.', NULL, NULL, 'Beginner', 'A hardy perennial herb with slender, spiky flower stems bearing bright blue florets, valued for its edible roots and leaves in Mediterranean and Middle Eastern cuisines. Extremely drought-tolerant once established and requires minimal maintenance.', 'Outdoor', false, false, NULL, true, 'Late Summer – Autumn', true, 'Spring – Summer', 'Moderate', 'Low', '{Well-draining,Sandy,Loamy}', 'Mediterranean Basin', 90, 45, false, 'https://static.inaturalist.org/photos/381386285/square.jpeg', 'https://static.inaturalist.org/photos/381386285/medium.jpeg', true, 973965, 52913, 'subspecies');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Cichorium intybus intybus', 'Blue sailors', 6.0, 7.5, false, '{Seeds,Division}', true, NULL, '2026-06-08 04:17:54.354107+00', NULL, 'Average', '{full_sun,part_shade}', 'Perennial', NULL, 'Check soil at 5 cm depth; allow top 2–3 cm to dry between waterings. Reduce frequency in winter.', 40, 70, 'Beginner', 'A hardy herbaceous perennial with striking blue flowers and deep taproots, widely naturalized across temperate regions. Grown as an ornamental, medicinal herb, and sustainable food crop (roots roasted as chicory coffee substitute).', 'Outdoor', false, false, NULL, true, 'Late Summer – Autumn', true, 'Summer – Early Autumn', 'Moderate', 'Low', '{Well-draining,Loamy,Rich}', 'Mediterranean Basin and Western Asia', 100, 45, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/15122359/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/15122359/medium.jpg', true, 518319, 52913, 'subspecies');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Stylidium', 'Triggerplants', 5.5, 6.5, false, '{Seeds,Division}', true, NULL, '2026-06-08 14:53:26.005375+00', NULL, 'Frequent', '{full_sun,part_shade}', 'Perennial', NULL, 'Keep soil consistently moist but not waterlogged during the growing season. Check soil moisture at the surface; allow only brief drying between waterings.', 50, 75, 'Advanced', 'Triggerplants are remarkable small herbs distinguished by a mobile, spring-loaded column that snaps closed when an insect lands, trapping pollen on the visitor. Native to Australia and Southeast Asia, they are highly specialized for insect pollination and require cool, moist, acidic growing conditions typical of their natural boggy habitats.', 'Outdoor', true, false, NULL, true, 'Summer – Autumn', true, 'Spring – Summer', 'Slow', 'High', '{}', 'Australia, Southeast Asia', 60, 30, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/164561538/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/164561538/medium.jpg', true, 123167, NULL, 'genus');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Cirsium palustre', 'Marsh thistle', 6.0, 7.5, false, '{Seeds}', true, NULL, '2026-06-08 14:53:26.005375+00', NULL, 'Frequent', '{full_sun,part_shade}', 'Biennial', NULL, 'Keep soil consistently moist during the growing season; check soil moisture at 5 cm depth and water when beginning to dry.', NULL, NULL, 'Beginner', 'A native European biennial thistle with spiny purple-pink flower heads and distinctive deeply lobed leaves, commonly found in wet meadows and marshy habitats. Valuable as a nectar source for pollinators and a host plant for specialized insects.', 'Outdoor', false, false, NULL, true, 'Late Summer – Autumn', true, 'Summer – Early Autumn', 'Moderate', 'Low', '{Loamy,Clay,Moisture-retaining}', 'Europe and temperate Western Asia', 150, 60, false, 'https://static.inaturalist.org/photos/390912739/square.jpeg', 'https://static.inaturalist.org/photos/390912739/medium.jpeg', true, 160623, 160623, 'species');
