INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Taraxacum officinale × platycarpum', 'Taraxacum officinale × platycarpum', 6.0, 7.5, false, '{Seeds,Division}', true, NULL, '2026-06-08 04:20:51.057526+00', NULL, 'Average', '{full_sun,part_shade}', 'Perennial', NULL, 'Keep soil consistently moist during active growth; allow surface to dry slightly between waterings. Reduce watering in dormancy.', NULL, NULL, 'Beginner', 'A vigorous hybrid dandelion combining traits of common dandelion (Taraxacum officinale) and flat-seeded dandelion (Taraxacum platycarpum). Hardy perennial herb with deeply lobed leaves and yellow flower heads, valued for culinary and medicinal use.', 'Outdoor', false, false, NULL, true, 'Late Spring – Early Summer', true, 'Spring – Early Summer', 'Fast', 'Low', '{Well-draining,Loamy,Sandy}', 'Temperate Europe and Asia (parent species)', 50, 45, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/620131139/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/620131139/medium.jpg', true, 1666060, 1666060, 'hybrid');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Taraxacum', 'Common dandelions', 6.0, 7.5, false, '{Seeds,Division}', true, NULL, '2026-06-08 04:20:51.057526+00', NULL, 'Minimum', '{full_sun,part_shade}', 'Perennial', NULL, 'Keep soil consistently moist during active growth; allow surface to dry between waterings. Drought-tolerant once established.', NULL, NULL, 'Beginner', 'A hardy, deep-rooted perennial herb with bright yellow flowers and deeply lobed leaves, widely recognized as both a common weed and a nutritious foraged plant. Extremely resilient, cold-hardy, and valued for edible leaves, roots, and flowers in culinary and medicinal applications.', 'Outdoor', false, false, NULL, true, 'Late Spring – Early Summer', true, 'Spring – Summer', 'Fast', 'Low', '{Well-draining,Sandy,Loamy,Poor}', 'Temperate Europe and Asia; naturalized worldwide', 50, 30, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/35280454/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/35280454/medium.jpg', true, 967514, NULL, 'section');
