INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Bidens bipinnata', 'Spanish needles', 6.0, 7.5, false, '{Seeds}', true, NULL, '2026-06-08 14:53:26.005375+00', NULL, 'Average', '{full_sun,part_shade}', 'Annual', NULL, 'Allow top 2–3 cm of soil to dry between waterings during growing season. Reduce moisture in dormancy.', 40, 70, 'Beginner', 'A branching annual herb with finely divided bipinnate foliage and small yellow flowers, native to warm Americas. Produces distinctive barbed needle-like seeds that easily disperse on clothing and fur, making it both a valued wildflower and persistent weedy species.', 'Outdoor', false, false, NULL, true, 'Late Summer – Autumn', true, 'Summer – Autumn', 'Fast', 'Low', '{Well-draining,Sandy,Loamy}', 'Tropical and subtropical Americas', 90, 60, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/331811108/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/331811108/medium.jpg', true, 50202, 50202, 'species');
