INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Chlorophytum comosum', 'Spider plant', 6.0, 7.5, false, '{"Offset Separation",Seeds}', true, NULL, '2026-05-31 00:46:12.714868+00', NULL, 'Average', '{"part shade"}', 'Perennial', 'Herbaceous Perennial', 'Allow top 2–3 cm of soil to dry between waterings. Check soil moisture at the surface regularly, especially during growing season.', 40, 60, 'Beginner', 'A vigorous, trailing houseplant with narrow, arching green or variegated leaves that form dense rosettes. Spider plants are exceptionally hardy and produce dangling stolons with plantlets, making them ideal for hanging baskets and shelf displays. Notable air-purifying qualities and remarkable tolerance for neglect.', 'Indoor', false, false, NULL, false, NULL, true, 'Spring – Summer', 'Fast', 'Low', '{Well-draining,Loamy}', 'Tropical West Africa', 30, 60, true, 'https://inaturalist-open-data.s3.amazonaws.com/photos/362493860/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/362493860/medium.jpeg', true, 322492, 322492, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Colocasia esculenta', 'Taro', 5.5, 7.0, true, '{Division,"Offset Separation"}', true, NULL, '2026-06-08 14:53:26.005375+00', 'Contains calcium oxalate crystals; ingestion causes oral irritation, difficulty swallowing, and gastrointestinal upset in pets.', 'Frequent', '{part_shade,filtered_indirect}', 'Perennial', NULL, 'Keep soil consistently moist but not waterlogged during growing season. Check soil at 2–3 cm depth; water when it feels slightly dry at this level.', 60, 80, 'Intermediate', 'A tropical aroid with large, arrow-shaped leaves and edible starchy corms, widely cultivated for its nutritional value and ornamental foliage. Prefers warm, humid conditions and consistently moist soil.', 'Both', true, true, 'Raw corms and leaves contain calcium oxalate crystals causing oral irritation and throat burning. Thorough cooking destroys oxalates, rendering corms safe for consumption. Sap may irritate sensitive skin.', false, NULL, true, 'Summer', 'Moderate', 'Medium', '{Well-draining,Loamy,Rich,Moisture-retaining}', 'Tropical Southeast Asia and the Indian subcontinent', 180, 90, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/20295281/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/20295281/medium.jpeg', true, 122835, 122835, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Kalanchoe blossfeldiana', 'Flaming katy', 6.0, 7.0, true, '{"Leaf Cuttings","Stem Cuttings",Seeds}', true, NULL, '2026-06-08 14:53:26.005375+00', 'All parts contain cardiac glycosides; ingestion by dogs, cats, and other pets may cause vomiting, diarrhea, abdominal pain, and potentially fatal cardiac arrhythmias.', 'Minimum', '{full_sun,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry completely between waterings. This succulent stores water in leaves and stems; overwatering causes root rot.', 30, 50, 'Beginner', 'A compact succulent subshrub with glossy, dark green leaves and dense clusters of bright red, orange, pink, or yellow flowers in winter to early spring. Prized as an indoor or balcony plant for cheerful long-lasting blooms and low maintenance.', 'Both', true, true, 'Contains cardiac glycosides; ingestion may cause gastrointestinal upset and potentially cardiac complications. Skin contact generally safe.', true, 'Late Winter – Spring', true, 'Winter – Early Spring', 'Moderate', 'Low', '{Well-draining,Sandy}', 'Madagascar', 30, 30, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/60054754/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/60054754/medium.jpeg', true, 164326, 164326, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Ophioglossidae', 'Adder''s-tongues, fork ferns, and allies', 5.5, 7.0, false, '{Division}', true, NULL, '2026-06-08 14:53:26.005375+00', NULL, 'Frequent', '{full_shade,filtered_indirect}', 'Perennial', NULL, 'Keep soil consistently moist but not waterlogged; check at surface and maintain moderate moisture at all times.', 60, 80, 'Advanced', 'A unique family of primitive ferns characterized by a distinctive fertile frond (the adder''s tongue or fork) that emerges separately from sterile foliage. These slow-growing woodland ferns are challenging to cultivate and prefer cool, moist, undisturbed conditions.', 'Both', false, false, NULL, false, NULL, false, NULL, 'Slow', 'High', '{Well-draining,Peaty,Moisture-retaining}', 'Temperate and subtropical regions worldwide, with centers of diversity in tropical montane forests', 45, 30, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/11877500/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/11877500/medium.jpg', true, 764795, NULL, 'subclass');
