INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Dysphania ambrosioides', 'Mexican tea', 6.0, 7.5, true, '{Seeds,"Stem Cuttings"}', true, NULL, '2026-06-08 14:53:26.005375+00', 'Contains saponins and essential oils that can cause gastrointestinal upset in dogs and cats if ingested.', 'Average', '{full_sun,part_shade}', 'Annual', NULL, 'Allow top 2–3 cm of soil to dry between waterings; this herb prefers moderate moisture but not waterlogged conditions.', 40, 70, 'Beginner', 'A fast-growing aromatic herb with feathery, deeply lobed leaves and a pungent, citrus-like scent. Traditionally used in herbal medicine and as a culinary flavoring, Mexican tea is valued for its digestive properties and essential oil content.', 'Both', false, false, NULL, true, 'Late Summer – Autumn', true, 'Summer – Early Autumn', 'Fast', 'Low', '{Well-draining,Sandy,Loamy}', 'Tropical and subtropical Americas, from southwestern North America to South America', 90, 60, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/84127806/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/84127806/medium.jpeg', true, 76746, 76746, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Delphinium consolida', 'Forking larkspur', 6.0, 7.5, true, '{Seeds}', true, NULL, '2026-06-08 14:53:26.005375+00', 'All parts of the plant, especially seeds and roots, contain toxic alkaloids. Ingestion by pets causes gastrointestinal distress, salivation, muscle tremors, and cardiac arrhythmias.', 'Average', '{full_sun,part_shade}', 'Annual', NULL, 'Allow soil surface to dry between waterings; check at 1–2 cm depth. Prefers slightly moist but not waterlogged conditions during growth.', NULL, NULL, 'Beginner', 'A slender-stemmed annual with deeply lobed foliage and tall spikes of blue, purple, pink, or white flowers arranged along the stem. Prized for cut flowers and cottage garden borders, it prefers cool growing conditions and direct sunlight.', 'Outdoor', false, true, 'Seeds and roots contain toxic alkaloids (delphinine and related compounds). Ingestion causes burning mouth sensations, salivation, gastrointestinal upset, and potential cardiac effects. Skin contact may cause irritation in sensitive individuals.', true, 'Summer – Early Autumn', true, 'Summer', 'Fast', 'Low', '{Well-draining,Loamy}', 'Mediterranean region and Western Asia', 60, 30, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/276209/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/276209/medium.jpg', true, 1445438, 1445438, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Spathiphyllum cochlearispathum', 'Spathiphyllum cochlearispathum', 5.5, 6.5, true, '{Division,"Stem Cuttings"}', true, NULL, '2026-06-07 18:09:50.300094+00', 'Contains calcium oxalate crystals; ingestion causes oral irritation, drooling, and difficulty swallowing in cats and dogs.', 'Frequent', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings. Prefers consistently moist (not waterlogged) conditions; drooping leaves signal water stress.', 60, 80, 'Beginner', 'A compact tropical aroid with narrow, spoon-shaped glossy green leaves and delicate white spathes. Prized for its elegant foliage, air-purifying qualities, and ability to thrive in moderate indoor light with minimal fuss.', 'Indoor', true, true, 'Sap and tissue contain calcium oxalate crystals; ingestion causes oral burning, throat irritation, and swelling. Skin contact may cause dermatitis in sensitive individuals.', false, NULL, true, 'Spring – Summer', 'Moderate', 'Low', '{Well-draining,Peaty,Rich}', 'Tropical Central and South America', 50, 45, true, 'https://inaturalist-open-data.s3.amazonaws.com/photos/13920578/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/13920578/medium.jpg', true, 277175, 277175, 'species');
