r', false, false, NULL, true, 'Autumn', true, 'Spring', 'Fast', 'Low', '{}', 'North America (Canada and northern United States)', 2000, 1000, false, 'https://static.inaturalist.org/photos/318921929/square.jpeg', 'https://static.inaturalist.org/photos/318921929/medium.jpeg', true, 49883, 49883, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Picea', 'Spruces', 5.0, 7.5, false, '{Seeds,"Stem Cuttings"}', true, NULL, '2026-06-08 15:02:20.60003+00', NULL, 'Average', '{full_sun,part_shade}', 'Perennial', NULL, 'Allow soil to dry slightly between waterings; check at 5 cm depth. Keep consistently moist but not waterlogged during growing season.', 40, 60, 'Intermediate', 'A large genus of evergreen coniferous trees with pyramidal form and needle-like foliage, ranging from dwarf cultivars to tall forest species. Spruces are prized for ornamental landscaping, windbreaks, and as popular Christmas trees, valued for their dense, symmetrical growth and year-round visual appeal.', 'Outdoor', false, false, NULL, false, NULL, false, NULL, 'Moderate', 'Low', '{Well-draining,Loamy,Sandy}', 'Northern Hemisphere temperate and boreal forests; Europe, North America, and Asia', 6000, 400, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/10967638/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/10967638/medium.jpeg', true, 63573, NULL, 'genus');
