INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Betula', 'Birches', 5.0, 7.5, false, '{Seeds,"Stem Cuttings"}', true, NULL, '2026-06-08 15:02:20.60003+00', NULL, 'Average', '{full_sun,part_shade}', 'Perennial', NULL, 'Keep soil consistently moist during growing season; check at 5 cm depth and water when dry to touch.', 40, 60, 'Intermediate', 'Fast-growing deciduous trees with distinctive white or papery bark, slender branches, and small catkins. Valued for ornamental foliage, timber production, and seasonal colour in temperate landscapes.', 'Outdoor', false, false, NULL, true, 'Summer – Autumn', true, 'Spring', 'Fast', 'Low', '{Well-draining,Sandy,Loamy,Peaty}', 'Northern Hemisphere, temperate regions of North America, Europe, and Asia', 2000, 1000, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/6293507/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/6293507/medium.jpg', true, 49156, NULL, 'genus');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Betulaceae', 'Birch family', 6.0, 7.5, false, '{Seeds,"Stem Cuttings"}', true, NULL, '2026-06-08 15:02:20.60003+00', NULL, 'Average', '{full_sun,part_shade}', 'Perennial', NULL, 'Allow top 2–5 cm of soil to dry between waterings; most species prefer consistently moist but well-draining soil during growing season.', NULL, NULL, 'Intermediate', 'Betulaceae is a diverse family of deciduous and semi-evergreen woody plants including birches, alders, and hazels, characterized by catkin-bearing flowers and typically simple, serrate leaves. Species range from ornamental landscape trees to shrubs valued for timber, catkins, and autumn colour.', 'Outdoor', false, false, NULL, true, 'Autumn', true, 'Spring', 'Moderate', 'Low', '{Well-draining,Loamy,Sandy}', 'Northern Hemisphere temperate and boreal regions; some genera extend to tropical highlands', NULL, NULL, false, 'https://static.inaturalist.org/photos/8119202/square.jpg', 'https://static.inaturalist.org/photos/8119202/medium.jpg', true, 49155, NULL, 'family');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Kindbergia praelonga', 'Common feather-moss', 5.5, 7.0, false, '{Division}', true, NULL, '2026-06-08 14:53:26.005375+00', NULL, 'Frequent', '{part_shade,full_shade}', 'Perennial', NULL, 'Mosses require constant moisture without waterlogging. Keep substrate consistently moist but ensure excellent drainage to prevent anaerobic conditions.', 70, 100, 'Beginner', 'A common feather-moss found in temperate woodlands and moist rocky habitats, characterized by delicate, branching fronds and soft green coloration. Valued in terrariums and moss gardens for aesthetic appeal and ecosystem support.', 'Both', false, false, NULL, false, NULL, false, NULL, 'Slow', 'Medium', '{Well-draining,Peaty,Moisture-retaining}', 'Temperate Northern Hemisphere including North America and Eurasia', 5, 15, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/54967207/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/54967207/medium.jpeg', true, 1122172, 1122172, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Carex sylvatica', 'European woodland sedge', 5.5, 7.0, false, '{Division,Seeds}', true, NULL, '2026-06-08 14:53:26.005375+00', NULL, 'Average', '{part_shade,full_shade}', 'Perennial', NULL, 'Keep soil consistently moist but not waterlogged; check soil moisture at 5 cm depth, ensuring it does not dry out completely.', NULL, NULL, 'Beginner', 'A low-growing woodland sedge with fine, arching green foliage, native to European forests. Valued for erosion control, ground cover, and naturalisation in shaded, moist woodland gardens.', 'Outdoor', false, false, NULL, true, 'Spring – Summer', true, 'Spring', 'Moderate', 'Low', '{Well-draining,Loamy,Peaty,Moisture-retaining}', 'Europe (temperate woodlands and grasslands)', 45, 60, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/151584811/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/151584811/medium.jpg', true, 69640, 69640, 'species');
