INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Abietoideae', 'Firs, hemlocks, cedars, and allies', 5.0, 7.0, false, '{Seeds}', true, NULL, '2026-06-08 15:02:20.60003+00', NULL, 'Average', '{full_sun,part_shade}', 'Perennial', NULL, 'Keep soil consistently moist but well-draining. Check at 5–8 cm depth; water when soil begins to dry slightly. Avoid waterlogging.', 40, 60, 'Intermediate', 'A diverse subfamily of large coniferous trees including firs (Abies), spruces (Picea), hemlocks (Tsuga), cedars (Cedrus, Thuja), and allies. These evergreen giants feature needle-like foliage and are prized for timber, ornamental landscaping, and reforestation. Many are extremely long-lived and drought-tolerant once established.', 'Outdoor', false, false, NULL, true, 'Autumn – Winter', true, 'Spring', 'Moderate', 'Low', '{Well-draining,Sandy,Loamy}', 'Northern temperate and boreal regions worldwide; native to North America, Europe, and Asia', 6000, 2000, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/259738118/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/259738118/medium.jpg', true, 1456299, NULL, 'subfamily');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Bromus rubens', 'Red brome', 6.0, 7.5, true, '{Seeds}', true, NULL, '2026-06-08 14:53:26.005375+00', 'Awns and seeds can cause mechanical injury to mouths, eyes, and digestive tracts of livestock and pets. May cause irritation or laceration on ingestion.', 'Minimum', '{full_sun}', 'Annual', NULL, 'Water moderately during active growth in cool season; allow soil surface to dry between waterings. This is an annual grass with minimal root depth requirements.', NULL, NULL, 'Beginner', 'A fast-growing annual grass native to the Mediterranean, characterized by reddish-purple awns and seed heads in late spring. Commonly found in arid and semi-arid regions as a winter annual; of minor ornamental interest but significant as an invasive species in western North America.', 'Outdoor', false, false, NULL, true, 'Late Spring – Early Summer', true, 'Spring – Early Summer', 'Fast', 'Low', '{Sandy,Well-draining,Poor}', 'Mediterranean Basin', 60, 30, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/32783733/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/32783733/medium.jpg', true, 59210, 59210, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Dietes grandiflora', 'Large fortnight lily', 6.0, 7.5, false, '{Division,Seeds}', true, NULL, '2026-06-08 14:53:26.005375+00', NULL, 'Average', '{full_sun,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings during the growing season. Reduce watering in winter.', 40, 60, 'Beginner', 'A clump-forming perennial with elegant iris-like leaves and delicate white flowers with yellow and purple markings, blooming repeatedly throughout the growing season. Extremely hardy and low-maintenance, ideal for borders and containers.', 'Outdoor', false, false, NULL, true, 'Summer – Autumn', true, 'Spring – Summer', 'Moderate', 'Low', '{Well-draining,Loamy}', 'South Africa', 75, 60, false, 'https://static.inaturalist.org/photos/89281565/square.jpg', 'https://static.inaturalist.org/photos/89281565/medium.jpg', true, 291342, 291342, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Pinaceae', 'Pine family', 5.0, 7.0, false, '{Seeds}', true, NULL, '2026-06-08 15:02:20.60003+00', NULL, 'Minimum', '{full_sun}', 'Perennial', NULL, 'Allow soil to dry moderately between waterings; conifers are drought-tolerant once established. Check soil moisture 5–8 cm deep.', NULL, NULL, 'Beginner', 'Pinaceae is a large, ancient family of evergreen conifers including pines, firs, spruces, larches, and hemlocks. These woody trees and shrubs are characterized by needle-like or scale-like foliage, resinous wood, and cone-bearing reproduction; they dominate temperate and boreal forests worldwide and are widely cultivated for timber, ornament, and erosion control.', 'Outdoor', false, false, NULL, true, 'Autumn – Winter', false, NULL, 'Moderate', 'Low', '{Well-draining,Sandy,Loamy,Poor}', 'Northern Hemisphere temperate and boreal zones; also Southeast Asia and Central America (genus-dependent)', NULL, NULL, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/275129245/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/275129245/medium.jpg', true, 47562, NULL, 'family');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Cirsium heterophyllum', 'Melancholy thistle', 6.0, 7.5, false, '{Seeds,Division}', true, NULL, '2026-06-08 14:53:26.005375+00', NULL, 'Average', '{full_sun,part_shade}', 'Perennial', NULL, 'Allow soil to dry slightly between waterings; check at surface level. Keep consistently moist during growing season but avoid waterlogging.', NULL, NULL, 'Beginner', 'A striking perennial thistle with distinctive purple-pink flower heads and greyish-green, variously lobed leaves. Native to montane meadows, it is valued for its ornamental appeal and attracts pollinators in cottage gardens and alpine settings.', 'Outdoor', false, false, NULL, true, 'Late Summer – Autumn', true, 'Summer', 'Moderate', 'Low', '{Well-draining,Loamy}', 'Northern Europe, including Scotland, Scandinavia, and Alpine regions', 60, 45, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/139588510/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/139588510/medium.jpeg', true, 332681, 332681, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Christella parasitica', 'Parasitic tri-vein fern', 5.0, 7.0, false, '{}', true, NULL, '2026-06-08 14:53:26.005375+00', NULL, 'Frequent', '{part_shade,filtered_indirect}', 'Perennial', NULL, 'Keep soil consistently moist but not waterlogged; check at the surface daily and water when the top layer begins to feel dry.', 60, 85, 'Intermediate', 'A delicate tropical fern featuring finely divided, feathery fronds with a characteristic tri-vein arrangement. Native to tropical Asia and the Pacific, it thrives in humid conditions and is prized for its intricate foliage in shade gardens and terrariums.', 'Both', true, false, NULL, false, NULL, false, NULL, 'Moderate', 'Medium', '{Well-draining,Peaty,Moisture-retaining}', 'Tropical Asia and Pacific Islands', 60, 45, true, 'https://inaturalist-open-data.s3.amazonaws.com/photos/346922412/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/346922412/medium.jpeg', true, 369396, 369396, 'species');
