INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Rosa ''Graham Thomas''', 'Graham thomas rose', 6.0, 6.5, false, '{"Stem Cuttings"}', true, NULL, '2026-06-08 15:17:01.415412+00', NULL, 'Average', '{full_sun}', 'Perennial', NULL, 'Check soil 5 cm deep; water when dry at this depth. Roses prefer consistent moisture but require good drainage to prevent root rot.', 40, 60, 'Intermediate', 'A modern shrub rose bred by David Austin with full, cupped flowers in warm apricot-yellow that fade to soft butter-yellow. Highly fragrant with a tea scent, vigorous growth habit, and excellent disease resistance; ideal for borders, containers, and cutting.', 'Outdoor', false, false, NULL, true, 'Autumn – Winter', true, 'Spring – Autumn', 'Fast', 'Medium', '{Well-draining,Loamy,Rich}', 'Garden hybrid (bred in England)', 150, 120, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/11763754/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/11763754/medium.jpg', true, 47132, NULL, 'order');
