INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Rosa ''Golden Celebration''', 'Golden celebration rose', 6.0, 6.5, false, '{"Stem Cuttings"}', true, NULL, '2026-06-08 15:17:01.422106+00', NULL, 'Average', '{full_sun}', 'Perennial', NULL, 'Check soil 5 cm deep; water thoroughly when dry at that depth. Roses prefer consistent moisture but not waterlogged conditions.', 40, 60, 'Intermediate', 'A modern shrub rose with full, quartered golden-yellow blooms that deepen in tone with age. Prized for its fragrance, disease resistance, and repeat flowering habit, making it an excellent choice for borders and specimen planting.', 'Outdoor', false, false, NULL, true, 'Autumn', true, 'Spring – Autumn', 'Moderate', 'Medium', '{Well-draining,Loamy,Rich}', 'Modern hybrid rose (garden origin, not wild species)', 120, 100, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/11763754/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/11763754/medium.jpg', true, 47132, NULL, 'order');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Tradescantia zebrina', 'Wandering dude', 6.0, 7.0, false, '{"Stem Cuttings",Division}', true, NULL, '2026-06-08 00:28:12.822862+00', NULL, 'Average', '{part_shade,filtered_indirect}', 'Perennial', NULL, 'Check soil at 2–3 cm depth; water when dry to touch. Allow brief drying between waterings but avoid prolonged drought.', 40, 80, 'Beginner', 'A vigorous trailing or climbing perennial with striking purple-backed, silver-striped foliage. Thrives in bright indirect light and is exceptionally easy to propagate and maintain, making it ideal for hanging baskets and shelves.', 'Indoor', true, false, NULL, false, NULL, true, 'Spring – Summer', 'Fast', 'Low', '{Well-draining,Loamy,Rich}', 'Central and South America', 15, 60, false, 'https://static.inaturalist.org/photos/100258841/square.jpeg', 'https://static.inaturalist.org/photos/100258841/medium.jpeg', true, 169883, 169883, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Viola mirabilis', 'Broad-leaved violet', 6.0, 7.5, false, '{Seeds,Division}', true, NULL, '2026-06-08 14:53:26.005375+00', NULL, 'Average', '{part_shade,filtered_indirect}', 'Perennial', NULL, 'Keep soil consistently moist but not waterlogged; check at the surface and water when the top 1–2 cm begins to dry.', 50, 70, 'Beginner', 'A low-growing woodland perennial with broad, heart-shaped leaves and delicate purple-violet flowers that bloom in spring. Known for producing cleistogamous (self-fertile) flowers later in the season, it is valued for shade gardens and naturalistic plantings.', 'Outdoor', false, false, NULL, true, 'Summer – Autumn', true, 'Spring – Early Summer', 'Moderate', 'Low', '{Loamy,Well-draining,Moisture-retaining}', 'Central and Eastern Europe', 30, 40, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/161434153/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/161434153/medium.jpeg', true, 483183, 483183, 'species');
