INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Platanus occidentalis', 'American sycamore', 5.5, 7.5, false, '{"Stem Cuttings",Seeds}', true, NULL, '2026-06-08 15:02:20.60003+00', NULL, 'Average', '{full_sun}', 'Perennial', NULL, 'Check soil at 5–8 cm depth; water when soil begins to dry. Prefers consistently moist but well-draining conditions during growing season.', NULL, NULL, 'Beginner', 'A massive deciduous tree native to eastern North America, distinguished by exfoliating pale bark and large palmate leaves that turn golden-brown in autumn. Commonly planted as an ornamental shade tree and timber species in riparian zones.', 'Outdoor', false, false, NULL, true, 'Autumn', true, 'Spring', 'Fast', 'Low', '{Well-draining,Loamy,Moisture-retaining}', 'Eastern North America (Atlantic and Mississippi drainage basins)', 4500, 3000, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/204738082/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/204738082/medium.jpg', true, 49662, 49662, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Pseudotsuga menziesii', 'Douglas-fir', 5.0, 7.0, false, '{Seeds}', true, NULL, '2026-06-08 15:02:20.60003+00', NULL, 'Minimum', '{full_sun}', 'Perennial', NULL, 'Allow soil to dry slightly between waterings in young seedlings; mature trees rely on natural rainfall and require no supplemental watering in suitable climates.', NULL, NULL, 'Intermediate', 'A large coniferous evergreen tree native to the Pacific Northwest, prized for timber production and distinctive flat needles with white bands on the underside. Highly adaptable to cool, moist climates and commonly used in reforestation and ornamental forestry.', 'Outdoor', false, false, NULL, true, 'Autumn', false, NULL, 'Moderate', 'Low', '{Well-draining,Loamy,Sandy}', 'Pacific Northwest North America', 7500, 350, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/140217013/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/140217013/medium.jpg', true, 48256, 48256, 'species');
