INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Phrymaceae', 'Lopseed family', 6.0, 7.5, false, '{Seeds,Division}', true, NULL, '2026-06-08 15:02:20.60003+00', NULL, 'Average', '{part_shade,filtered_indirect}', 'Perennial', NULL, 'Keep soil consistently moist but not waterlogged; check soil moisture at 2–3 cm depth during growing season.', NULL, NULL, 'Beginner', 'A woodland perennial with slender, arching flower spikes bearing tiny rose or lavender flowers arranged in a distinctive lopsided (secund) pattern. Native to eastern North American forests, it thrives in shade gardens and naturalized settings with minimal intervention.', 'Outdoor', false, false, NULL, true, 'Late Summer – Autumn', true, 'Summer', 'Moderate', 'Low', '{Well-draining,Loamy,Rich}', 'Eastern North America', 80, 40, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/396710558/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/396710558/medium.jpeg', true, 64552, NULL, 'family');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Sambucus javanica', 'Chinese elder', 6.0, 7.5, true, '{"Stem Cuttings",Seeds,Division}', true, NULL, '2026-06-08 14:53:26.005375+00', 'Unripe berries and stems contain cyanogenic glycosides; all parts except ripe berries are potentially toxic to pets if ingested in quantity.', 'Average', '{full_sun,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings during growing season; reduce frequency in winter.', 50, 70, 'Intermediate', 'A fast-growing deciduous shrub to small tree native to Southeast Asia, bearing compound leaves and clusters of small white or pink flowers followed by dark purple berries prized for culinary and medicinal use.', 'Both', false, true, 'Unripe berries and stems contain cyanogenic glycosides; only fully ripe berries are safe for consumption. Raw or undercooked berries may cause nausea and gastrointestinal distress.', true, 'Late Summer–Autumn', true, 'Late Spring–Summer', 'Fast', 'Medium', '{Well-draining,Loamy,Rich}', 'Tropical and subtropical Southeast Asia (Java, China, Thailand)', 400, 300, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/12256480/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/12256480/medium.jpeg', true, 474166, 474166, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Axonopus compressus', 'Broadleaf carpetgrass', 5.0, 7.0, false, '{Division,Seeds}', true, NULL, '2026-06-08 14:53:26.005375+00', NULL, 'Average', '{part_shade,filtered_indirect}', 'Perennial', NULL, 'Keep soil consistently moist during establishment and growing season; allow surface to dry slightly between waterings once established. For established lawns, water when top 2–3 cm becomes dry.', 60, 85, 'Beginner', 'A low-growing tropical grass species with broad, soft blades, primarily used as a ground cover and forage grass in warm, humid climates. Tolerates shade and moist soils, making it ideal for subtropical turf applications.', 'Outdoor', true, false, NULL, false, NULL, true, 'Summer', 'Moderate', 'Low', '{Well-draining,Loamy,Moisture-retaining}', 'Tropical Americas and West Indies', 15, NULL, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/498557114/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/498557114/medium.jpeg', true, 159110, 159110, 'species');
