INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Opuntia engelmannii var. lindheimeri', 'Texas prickly pear', 6.0, 7.5, false, '{"Offset Separation",Seeds}', true, NULL, '2026-06-08 15:25:29.168782+00', NULL, 'Minimum', '{full_sun}', 'Perennial', NULL, 'Allow soil to dry completely between waterings. For potted specimens, water deeply only when soil is bone-dry, typically every 3–4 weeks in growing season.', NULL, NULL, 'Beginner', 'A sprawling succulent cactus with flat, paddle-shaped stems (cladodes) covered in sharp spines, native to Texas and northern Mexico. Known for producing vibrant yellow flowers and edible purple fruits (tunas), it is extremely drought-tolerant and requires minimal care.', 'Outdoor', false, false, NULL, true, 'Summer – Autumn', true, 'Spring – Summer', 'Moderate', 'Low', '{Well-draining,Sandy,Poor}', 'Texas and northern Mexico', 150, 200, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/417243183/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/417243183/medium.jpg', true, 78264, 78264, 'species');
