INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Opuntia engelmannii', 'Engelmann''s prickly pear', 6.0, 8.0, false, '{"Offset Separation",Seeds}', true, NULL, '2026-06-08 15:25:29.175727+00', NULL, 'Minimum', '{full_sun}', 'Perennial', NULL, 'Let soil dry completely between waterings. Check soil depth of 5–7 cm; water only when bone-dry.', NULL, NULL, 'Beginner', 'A hardy xerophytic Opuntia native to southwestern North America, characterized by flat, paddle-shaped green cladodes armed with sharp spines and glochids. Produces vibrant yellow flowers in spring, followed by edible purplish-red fruits; extremely drought-tolerant and low-maintenance.', 'Outdoor', false, false, NULL, true, 'Summer – Autumn', true, 'Spring – Early Summer', 'Moderate', 'Low', '{Well-draining,Sandy,Poor}', 'Southwestern United States (Texas, Arizona, New Mexico) and northern Mexico', 150, 200, false, 'https://static.inaturalist.org/photos/105512746/square.jpeg', 'https://static.inaturalist.org/photos/105512746/medium.jpeg', true, 1492999, NULL, 'complex');
