INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Betula pendula', 'Silver birch', 5.0, 7.0, false, '{Seeds}', true, NULL, '2026-06-08 15:02:20.60003+00', NULL, 'Average', '{full_sun}', 'Perennial', NULL, 'Keep soil consistently moist during establishment; mature trees are drought-tolerant once established. Check soil moisture at 5–10 cm depth during growing season.', NULL, NULL, 'Beginner', 'A deciduous tree with distinctive white papery bark and delicate, pendulous branches bearing fine-textured foliage. Prized as an ornamental and pioneer species for its elegant silhouette, rapid growth, and ecological value in temperate woodland.', 'Outdoor', false, false, NULL, true, 'Autumn', true, 'Spring', 'Fast', 'Low', '{Well-draining,Sandy,Loamy}', 'Northern Europe, Western Asia, and northern temperate regions', 25000, 10000, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/36257611/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/36257611/medium.jpeg', true, 83992, 83992, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Tsuga canadensis', 'Eastern hemlock', 5.0, 7.0, false, '{Seeds,"Stem Cuttings"}', true, NULL, '2026-06-08 15:02:20.60003+00', NULL, 'Average', '{full_sun,part_shade}', 'Perennial', NULL, 'Keep soil consistently moist but not waterlogged; check at 5 cm depth — allow surface to dry slightly between waterings in drier months.', 40, 70, 'Intermediate', 'A slow-growing, evergreen conifer native to eastern North America with fine, feathery foliage and an elegant pyramidal form. Valued for timber, ornamental landscapes, and wildlife habitat, though susceptible to hemlock woolly adelgid in warmer regions.', 'Outdoor', false, false, NULL, true, 'Autumn – Winter', true, 'Spring', 'Slow', 'Medium', '{Well-draining,Loamy,Peaty}', 'Eastern North America, from Nova Scotia to North Carolina and westward to Minnesota and Tennessee', 2000, 900, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/400071107/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/400071107/medium.jpeg', true, 48734, 48734, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Maianthemum racemosum', 'False solomon''s seal', 5.0, 7.0, true, '{Division,Seeds}', true, NULL, '2026-06-08 15:30:34.312792+00', 'Berries and foliage are toxic to cats and dogs. Ingestion may cause gastrointestinal upset, including vomiting and diarrhea.', 'Average', '{part_shade,full_shade}', 'Perennial', NULL, 'Keep soil consistently moist but not waterlogged. Check soil at 2–3 cm depth; water when this layer becomes barely moist.', 50, 75, 'Beginner', 'A delicate, shade-loving perennial with elegant arching stems bearing oval leaflets and delicate white flowers in spring, followed by red berries that ripen to dark purple. Native to North American woodlands, it adds woodland charm to shaded garden settings.', 'Outdoor', false, true, 'Berries are toxic if ingested in quantity. Gastrointestinal upset, including nausea and vomiting, may result. Not typically dangerous with incidental contact.', true, 'Late Summer – Autumn', true, 'Spring', 'Moderate', 'Low', '{Well-draining,Loamy,Rich,Moisture-retaining}', 'North America (eastern and central regions)', 60, 45, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/111809822/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/111809822/medium.jpg', true, 51062, 51062, 'species');
