alse, NULL, false, NULL, true, 'Summer', 'Moderate', 'Low', '{Well-draining,Loamy,Rich}', 'Eastern Mediterranean and Central Asia', 60, 20, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/63378263/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/63378263/medium.jpg', true, 1080363, NULL, 'complex');
