INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Monstera deliciosa ''Variegata''', 'Variegated swiss cheese plant', 6.0, 7.0, true, '{"Stem Cuttings","Air Layering"}', true, '{"id": 5258, "genus": "Monstera", "family": "Araceae", "hybrid": null, "variety": null, "cultivar": "Variegata", "authority": null, "other_name": [], "subspecies": null, "common_name": "variegated Swiss cheese plant", "default_image": {"license": 451, "small_url": "https://s3.us-central-1.wasabisys.com/perenual/image/upgrade_access.jpg?X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Credential=0MPGHU7CIPXNPMVWMXUW%2F20260605%2Fus-central-1%2Fs3%2Faws4_request&X-Amz-Date=20260605T044443Z&X-Amz-SignedHeaders=host&X-Amz-Expires=86400&X-Amz-Signature=5e20621b9901c2eef82db56ee0efae2755146d605e2bf6b14ee57bfb44804bf4", "thumbnail": "https://s3.us-central-1.wasabisys.com/perenual/image/upgrade_access.jpg?X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Credential=0MPGHU7CIPXNPMVWMXUW%2F20260605%2Fus-central-1%2Fs3%2Faws4_request&X-Amz-Date=20260605T044443Z&X-Amz-SignedHeaders=host&X-Amz-Expires=86400&X-Amz-Signature=5e20621b9901c2eef82db56ee0efae2755146d605e2bf6b14ee57bfb44804bf4", "medium_url": "https://s3.us-central-1.wasabisys.com/perenual/image/upgrade_access.jpg?X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Credential=0MPGHU7CIPXNPMVWMXUW%2F20260605%2Fus-central-1%2Fs3%2Faws4_request&X-Amz-Date=20260605T044443Z&X-Amz-SignedHeaders=host&X-Amz-Expires=86400&X-Amz-Signature=5e20621b9901c2eef82db56ee0efae2755146d605e2bf6b14ee57bfb44804bf4", "license_url": "https://creativecommons.org/publicdomain/zero/1.0/", "regular_url": "https://s3.us-central-1.wasabisys.com/perenual/image/upgrade_access.jpg?X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Credential=0MPGHU7CIPXNPMVWMXUW%2F20260605%2Fus-central-1%2Fs3%2Faws4_request&X-Amz-Date=20260605T044443Z&X-Amz-SignedHeaders=host&X-Amz-Expires=86400&X-Amz-Signature=5e20621b9901c2eef82db56ee0efae2755146d605e2bf6b14ee57bfb44804bf4", "license_name": "CC0 1.0 Universal (CC0 1.0) Public Domain Dedication", "original_url": "https://s3.us-central-1.wasabisys.com/perenual/image/upgrade_access.jpg?X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Credential=0MPGHU7CIPXNPMVWMXUW%2F20260605%2Fus-central-1%2Fs3%2Faws4_request&X-Amz-Date=20260605T044443Z&X-Amz-SignedHeaders=host&X-Amz-Expires=86400&X-Amz-Signature=5e20621b9901c2eef82db56ee0efae2755146d605e2bf6b14ee57bfb44804bf4"}, "scientific_name": ["Monstera deliciosa ''Variegata''"], "species_epithet": "deliciosa"}', '2026-05-30 18:50:55.215794+00', 'Crystals of calcium oxalate present in stems and leaves cause oral irritation, drooling, and difficulty swallowing in cats and dogs if chewed or ingested.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings. Check soil moisture at this depth before watering; do not allow the plant to dry completely.', 50, 70, 'Intermediate', 'A climbing aroid with large fenestrated leaves featuring creamy white or yellow variegation, prized for dramatic foliage and air-purifying qualities. Slower growing and more light-sensitive than unvariegated Monstera deliciosa due to reduced chlorophyll.', 'Indoor', true, true, 'Chewing or ingesting stem and leaf tissue causes mouth and throat irritation, burning sensation, and difficulty swallowing due to calcium oxalate crystals. Sap may cause contact dermatitis or skin irritation in sensitive individuals.', false, NULL, true, 'Spring – Summer', 'Moderate', 'Medium', '{Well-draining,Loamy,Rich}', 'Central America (Mexico)', 200, 60, true, 'https://static.inaturalist.org/photos/10534833/square.jpeg', 'https://static.inaturalist.org/photos/10534833/medium.jpeg', true, 122521, 122521, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Ophrys sphegodes', 'Early spider-orchid', 7.0, 8.5, false, '{Seeds,Division}', true, NULL, '2026-06-08 15:02:20.60003+00', NULL, 'Average', '{full_sun,part_shade}', 'Perennial', NULL, 'Keep soil consistently moist but not waterlogged during growing season; allow slight drying between waterings. Reduce moisture during dormancy.', 50, 70, 'Advanced', 'A terrestrial Mediterranean orchid with small, distinctive flowers that mimic female solitary wasps to facilitate pollination. Produces delicate blooms in early spring with brownish-red sepals and a velvety, insect-shaped labellum.', 'Outdoor', false, false, NULL, false, NULL, true, 'Early Spring', 'Slow', 'High', '{Well-draining,Chalky,Loamy}', 'Mediterranean Basin (Southern Europe and North Africa)', 40, 15, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/132070082/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/132070082/medium.jpg', true, 243623, 243623, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Picea mariana', 'Black spruce', 4.5, 6.5, false, '{Seeds}', true, NULL, '2026-06-08 15:02:20.60003+00', NULL, 'Average', '{full_sun}', 'Perennial', NULL, 'Keep soil consistently moist but not waterlogged; check at 5 cm depth. Allow soil surface to dry slightly between waterings in established trees.', NULL, NULL, 'Intermediate', 'A hardy, slow-growing evergreen conifer native to boreal forests of North America, with a narrow pyramidal form, dense dark-green foliage, and small purple cones. Highly cold-tolerant and adapted to wet, acidic soils in subarctic climates.', 'Outdoor', false, false, NULL, true, 'Autumn – Winter', true, 'Spring', 'Slow', 'Low', '{}', 'Boreal forests of Canada and northern United States', 1500, 600, false, 'https://static.inaturalist.org/photos/77491970/square.jpg', 'https://static.inaturalist.org/photos/77491970/medium.jpg', true, 84296, 84296, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Allium stellatum', 'Prairie onion', 6.0, 7.5, false, '{Seeds,"Offset Separation"}', true, '{"id": 694, "genus": "Allium", "family": "Amaryllidaceae", "hybrid": null, "variety": null, "cultivar": null, "authority": null, "other_name": ["Prairie Onion", "Glade Onion", "Glade Onion"], "subspecies": null, "common_name": "prairie onion", "default_image": {"license": 45, "small_url": "https://s3.us-central-1.wasabisys.com/perenual/species_image/694_allium_stellatum/small/Allium_lusitanicum_003.jpg?X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Credential=0MPGHU7CIPXNPMVWMXUW%2F20260606%2Fus-central-1%2Fs3%2Faws4_request&X-Amz-Date=20260606T071214Z&X-Amz-SignedHeaders=host&X-Amz-Expires=86400&X-Amz-Signature=0f1e7d367e0b2c9b4aac2f4864f2dd2c5b9ded3a1339817414a691a27aa63bb1", "thumbnail": "https://s3.us-central-1.wasabisys.com/perenual/species_image/694_allium_stellatum/thumbnail/Allium_lusitanicum_003.jpg?X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Credential=0MPGHU7CIPXNPMVWMXUW%2F20260606%2Fus-central-1%2Fs3%2Faws4_request&X-Amz-Date=20260606T071214Z&X-Amz-SignedHeaders=host&X-Amz-Expires=86400&X-Amz-Signature=bfa30a25dff5cf3f8664c71448a3952841592e97d5036f93b2b96c37718ca6c2", "medium_url": "https://s3.us-central-1.wasabisys.com/perenual/species_image/694_allium_stellatum/medium/Allium_lusitanicum_003.jpg?X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Credential=0MPGHU7CIPXNPMVWMXUW%2F20260606%2Fus-central-1%2Fs3%2Faws4_request&X-Amz-Date=20260606T071214Z&X-Amz-SignedHeaders=host&X-Amz-Expires=86400&X-Amz-Signature=1358e9f4634a7290110aee89f869ce5a6f3a631131fc4d49cce341690f10fb5d", "license_url": "https://creativecommons.org/licenses/by-sa/3.0/deed.en", "regular_url": "https://s3.us-central-1.wasabisys.com/perenual/species_image/694_allium_stellatum/regular/Allium_lusitanicum_003.jpg?X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Credential=0MPGHU7CIPXNPMVWMXUW%2F20260606%2Fus-central-1%2Fs3%2Faws4_request&X-Amz-Date=20260606T071214Z&X-Amz-SignedHeaders=host&X-Amz-Expires=86400&X-Amz-Signature=0003af563650704d8e3978e8b418642bf5a080d519470da51dc403c1a41703e9", "license_name": "Attribution-ShareAlike 3.0 Unported (CC BY-SA 3.0)", "original_url": "https://s3.us-central-1.wasabisys.com/perenual/species_image/694_allium_stellatum/og/Allium_lusitanicum_003.jpg?X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Credential=0MPGHU7CIPXNPMVWMXUW%2F20260606%2Fus-central-1%2Fs3%2Faws4_request&X-Amz-Date=20260606T071214Z&X-Amz-SignedHeaders=host&X-Amz-Expires=86400&X-Amz-Signature=9af9830c5b62d99a7adb903c49ae23d1c4b1daaf2cb4172cc65beadd12fa4def"}, "scientific_name": ["Allium stellatum"], "species_epithet": "stellatum"}', '2026-06-06 07:12:14.727507+00', NULL, 'Minimum', '{full_sun,part_shade}', 'Perennial', NULL, 'Allow soil to dry between waterings; check soil moisture 3–5 cm deep. Once established, extremely drought-tolerant.', NULL, NULL, 'Beginner', 'A hardy North American prairie bulb with delicate star-shaped pink to rose flowers clustered atop slender stems, prized for drought tolerance and pollinator attraction in native plantings.', 'Outdoor', false, false, NULL, true, 'Summer – Early Autumn', true, 'Summer', 'Moderate', 'Low', '{Well-draining,Sandy,Poor}', 'Central and Northern Great Plains, North America', 60, 20, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/360999/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/360999/medium.jpg', true, 119790, 119790, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Aloe davyana', 'Highveld spotted aloe', 6.0, 7.5, true, '{"Offset Separation",Seeds}', true, NULL, '2026-06-08 01:14:33.679222+00', 'Latex and aloin compounds in leaves can cause gastrointestinal upset, vomiting, and diarrhea in cats and dogs if ingested.', 'Minimum', '{full_sun,part_shade}', 'Perennial', NULL, 'Let soil dry completely between waterings. Check at soil depth of 5 cm; water only when bone dry.', 30, 50, 'Beginner', 'A compact, clump-forming succulent endemic to the South African Highveld, distinguished by spotted or speckled leaf rosettes and tubular yellow flowers. Extremely drought-tolerant and low-maintenance, ideal for xeriscaping and container cultivation.', 'Both', false, true, 'Aloin in latex is a potent cathartic; ingestion causes severe gastrointestinal cramps and diarrhea. Skin contact may irritate sensitive individuals.', true, 'Summer – Early Autumn', true, 'Spring – Early Summer', 'Slow', 'Low', '{Well-draining,Sandy}', 'South Africa (Highveld region)', 30, 25, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/137193080/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/137193080/medium.jpeg', true, 1487466, 1487466, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Aloe maculata', 'Soap aloe', 6.0, 7.5, true, '{"Offset Separation",Seeds}', true, NULL, '2026-06-08 01:14:33.679222+00', 'Aloe latex (yellow sap under the leaf skin) is a potent laxative and can cause gastrointestinal distress, vomiting, and diarrhea in cats and dogs if ingested.', 'Minimum', '{full_sun,part_shade}', 'Perennial', NULL, 'Let soil dry completely between waterings. Check soil depth at 5–7 cm; water only when fully dry.', 30, 50, 'Beginner', 'A clump-forming succulent with mottled grey-green rosette leaves and tuberous roots, producing tall spikes of yellow tubular flowers. Prized for drought tolerance and ornamental foliage, historically used in soap-making traditions.', 'Both', false, true, 'Aloe latex (the yellow substance beneath the leaf cuticle) is a strong purgative; ingestion causes severe cramping and diarrhea. Skin contact with latex may cause dermatitis in sensitive individuals.', true, 'Late Spring – Summer', true, 'Spring – Summer', 'Moderate', 'Low', '{Well-draining,Sandy}', 'South Africa', 40, 60, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/122711137/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/122711137/medium.jpeg', true, 75379, 75379, 'species');
