INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Scindapsus pictus', 'Scindapsus pictus', 6.0, 6.5, true, '{"Stem Cuttings","Air Layering"}', true, NULL, '2026-06-07 16:24:32.18243+00', 'Contains calcium oxalate crystals; causes oral irritation, drooling, and difficulty swallowing in cats and dogs if ingested.', 'Average', '{filtered_indirect,part_shade}', 'Perennial', NULL, 'Allow top 2–3 cm of soil to dry between waterings; check soil moisture at the surface before watering.', 50, 75, 'Intermediate', 'A trailing tropical aroid with heart-shaped leaves distinctly marked with silver-white spots and variegation. Prized for its ornamental foliage and moderate air-purifying capability, thriving in humid indoor environments.', 'Indoor', true, true, 'Sap and leaf tissue contain calcium oxalate crystals; ingestion causes oral irritation, mouth pain, and throat discomfort. Skin contact may cause mild irritation in sensitive individuals.', false, NULL, false, NULL, 'Moderate', 'Medium', '{Well-draining,Loamy,Peaty}', 'Southeast Asia (Thailand, Indonesia)', NULL, 180, true, 'https://inaturalist-open-data.s3.amazonaws.com/photos/208689255/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/208689255/medium.jpeg', true, 346616, 346616, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Ophrys lutea', 'Yellow bee-orchid', 6.0, 7.5, false, '{Seeds,Division}', true, NULL, '2026-06-08 15:02:20.60003+00', NULL, 'Minimum', '{full_sun,part_shade}', 'Perennial', NULL, 'Keep substrate barely moist during growth phase; allow to dry between waterings. During dormancy, water minimally.', 40, 65, 'Advanced', 'A Mediterranean terrestrial orchid with small yellow flowers that mimic female bees to attract pollinators. Highly specialized and difficult to cultivate outside its native habitat, requiring precise dormancy cycles and well-draining, nutrient-poor soil.', 'Outdoor', false, false, NULL, false, NULL, true, 'Spring', 'Slow', 'High', '{Well-draining,Sandy,Poor}', 'Mediterranean Basin (Spain, France, Italy, Greece, North Africa)', 30, 10, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/13103/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/13103/medium.jpg', true, 59339, 59339, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Aloe arborescens', 'Candelabra aloe', 6.0, 8.0, true, '{"Stem Cuttings","Offset Separation",Seeds}', true, NULL, '2026-06-08 01:14:33.679222+00', 'Latex contains anthraquinones which can cause gastrointestinal upset, vomiting, and diarrhoea in cats and dogs if ingested.', 'Minimum', '{full_sun,part_shade}', 'Perennial', NULL, 'Allow soil to dry completely between waterings. Check soil moisture 5–7 cm deep; water only when bone dry.', 30, 50, 'Beginner', 'A succulent shrub with tall, branching rosettes of narrow greyish-green leaves and distinctive tubular golden-orange to red flowers held in dense racemes. Prized for its dramatic architectural form and adaptability to arid, sunny environments.', 'Outdoor', false, true, 'Latex contains anthraquinones with strong purgative effects. Ingestion of latex causes severe gastroenteritis. Latex contact may cause dermatitis and photosensitivity in susceptible individuals.', true, 'Spring – Summer', true, 'Late Winter – Spring', 'Moderate', 'Low', '{Well-draining,Sandy,Poor}', 'Eastern Cape and KwaZulu-Natal, South Africa', 300, 200, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/221831309/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/221831309/medium.jpeg', true, 81518, 81518, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Ophrys tenthredinifera', 'Sawfly orchid', 6.0, 7.5, false, '{Seeds,Division}', true, NULL, '2026-06-08 15:02:20.60003+00', NULL, 'Average', '{part_shade,filtered_indirect}', 'Perennial', NULL, 'Keep substrate moist during active growth in spring; allow to dry slightly between waterings during dormancy. Check at soil surface.', 50, 70, 'Advanced', 'A terrestrial orchid native to Mediterranean regions, recognized by its small flowers with dark reddish-brown sepals and petals, and a distinctive velvety lip that mimics sawfly insects to attract pollinators. Highly specialized and challenging to cultivate outside its native habitat.', 'Outdoor', false, false, NULL, false, NULL, true, 'Spring', 'Slow', 'High', '{Well-draining,Chalky}', 'Mediterranean Basin, Southern Europe', 30, 15, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/495208635/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/495208635/medium.jpg', true, 59335, 59335, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Aloe ferox', 'Cape aloe', 6.5, 7.5, true, '{"Offset Separation",Seeds}', true, NULL, '2026-06-08 01:14:33.679222+00', 'Latex contains anthraquinones which can cause gastrointestinal upset, vomiting, and diarrhea in cats and dogs if ingested.', 'Minimum', '{full_sun}', 'Perennial', NULL, 'Let soil dry completely between waterings. Check soil at depth; water only when bone-dry.', 30, 50, 'Beginner', 'A robust succulent shrub with thick blue-green leaves forming dense rosettes, native to South Africa. Valued for its striking appearance and traditional medicinal latex; highly drought-tolerant and ideal for arid landscapes.', 'Both', false, true, 'Latex and bitter compounds can cause severe gastrointestinal disturbances, cramping, and diarrhea if ingested internally. Skin contact may cause irritation in sensitive individuals.', false, NULL, true, 'Spring – Summer', 'Slow', 'Low', '{Well-draining,Sandy,Poor}', 'South Africa (Eastern Cape Province)', 300, 200, false, 'https://static.inaturalist.org/photos/372083060/square.jpeg', 'https://static.inaturalist.org/photos/372083060/medium.jpeg', true, 124412, 124412, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Aloe vera', 'Aloe vera', 7.0, 8.5, true, '{"Offset Separation",Seeds}', true, NULL, '2026-05-31 00:46:12.714868+00', 'Ingestion of latex (yellow sap under the leaf skin) causes severe gastrointestinal distress, vomiting, and diarrhea in dogs and cats. The clear gel is generally safe.', 'Minimum', '{"full sun","part shade"}', 'Perennial', 'Succulent', 'Let soil dry completely between waterings. Check soil 5–7 cm deep; water only when bone dry. Overwatering is the primary cause of failure.', NULL, NULL, 'Beginner', 'A drought-tolerant succulent with thick, fleshy leaves containing soothing clear gel. Highly valued for medicinal and cosmetic applications, it requires minimal water and thrives in bright, warm conditions.', 'Both', false, false, 'The clear inner gel is safe for topical and oral use (widely used in skincare and traditional medicine). The yellow latex sap under the leaf epidermis is a potent laxative and should not be ingested.', false, NULL, true, 'Spring – Summer', 'Moderate', 'Low', '{Well-draining,Sandy}', 'Arabian Peninsula (likely origin); now naturalized across Mediterranean, North Africa, and arid regions', 60, 60, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/340224811/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/340224811/medium.jpg', true, 126882, 126882, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Ophrys scolopax', 'Woodcock orchid', 6.0, 7.5, false, '{Seeds,Division}', true, NULL, '2026-06-08 15:02:20.60003+00', NULL, 'Average', '{part_shade,filtered_indirect}', 'Perennial', NULL, 'Keep substrate lightly moist during growing season; allow to dry somewhat during dormancy. Check at surface level.', 50, 70, 'Advanced', 'A Mediterranean terrestrial orchid with striking flowers resembling a female woodcock wasp, featuring dark sepals and a velvety brown labellum with distinctive patterning. Highly specialized for insect pollination and requires specific dormancy and soil conditions to thrive in cultivation.', 'Outdoor', false, false, NULL, true, 'Summer', true, 'Spring', 'Slow', 'High', '{Well-draining,Sandy,Peaty,Poor}', 'Mediterranean Basin (Southern Europe, North Africa)', 40, 15, false, 'https://static.inaturalist.org/photos/29234529/square.jpeg', 'https://static.inaturalist.org/photos/29234529/medium.jpeg', true, 82865, 82865, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Araucaria araucana', 'Monkey-puzzle', 5.5, 7.0, false, '{Seeds}', true, NULL, '2026-06-08 15:02:20.60003+00', NULL, 'Average', '{full_sun,part_shade}', 'Perennial', NULL, 'Allow soil to dry slightly between waterings; check at 2–3 cm depth. Prefers consistently moist but well-draining substrate during growing season.', 50, 70, 'Advanced', 'A slow-growing coniferous evergreen with distinctive triangular, sharply-pointed leaves arranged in dense spirals along thick branches, creating a striking architectural silhouette. Native to South American temperate forests, it is prized as an ornamental specimen plant but demands cool conditions and careful moisture management.', 'Both', false, false, NULL, true, 'Autumn – Winter', false, NULL, 'Slow', 'High', '{Well-draining,Loamy,Peaty}', 'South America (Chile and Argentina, Andes Mountains)', 1500, 800, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/176887961/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/176887961/medium.jpg', true, 126404, 126404, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Alopecurus pratensis', 'Meadow foxtail', 5.5, 7.5, false, '{Seeds,Division}', true, NULL, '2026-06-08 01:14:33.679222+00', NULL, 'Average', '{full_sun,part_shade}', 'Perennial', NULL, 'Keep soil consistently moist during growing season; allow surface to dry slightly between waterings in dormancy.', NULL, NULL, 'Beginner', 'A cool-season perennial grass native to temperate Europe, characterised by soft, dense tufts and distinctive fox-tail-like inflorescences. Widely used in meadow restoration, pasture improvement, and ornamental plantings for its attractive seedheads and ecological value.', 'Outdoor', false, false, NULL, true, 'Late Spring – Early Summer', true, 'Late Spring – Early Summer', 'Moderate', 'Low', '{Well-draining,Loamy,Moisture-retaining}', 'Temperate Europe and Western Asia', 80, 60, false, 'https://static.inaturalist.org/photos/389843432/square.jpeg', 'https://static.inaturalist.org/photos/389843432/medium.jpeg', true, 71141, 71141, 'species');
