INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Aloidendron dichotomum', 'Quiver tree', 6.0, 7.5, false, '{Seeds,"Stem Cuttings"}', true, NULL, '2026-06-08 01:14:33.679222+00', NULL, 'Minimum', '{full_sun}', 'Perennial', NULL, 'Let soil dry completely between waterings. Check at 5–7 cm depth; water only when soil is bone-dry.', 30, 50, 'Intermediate', 'A striking succulent tree native to southern Africa, featuring distinctive dichotomous branching and columnar grey-green stems crowned with rosettes of yellow-green leaves. Highly drought-tolerant and architecturally dramatic, prized for xeriscape and container cultivation.', 'Outdoor', false, false, NULL, true, 'Summer', true, 'Winter – Spring', 'Slow', 'Low', '{Well-draining,Sandy,Poor}', 'Southern Africa (Namibia and South Africa)', 600, 250, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/142408999/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/142408999/medium.jpg', true, 527446, 527446, 'species');
