INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Yucca aloifolia', 'Aloe yucca', 6.0, 7.5, true, '{"Offset Separation",Seeds}', true, NULL, '2026-06-08 01:14:33.679222+00', 'Saponins in foliage cause gastrointestinal upset and dermatitis in dogs and cats. Sharp leaf edges can also cause physical injury.', 'Minimum', '{full_sun,part_shade}', 'Perennial', NULL, 'Let soil dry completely between waterings. Check soil at 5–7 cm depth; water only when completely dry.', 30, 50, 'Beginner', 'A striking succulent shrub with sharp, sword-like grey-green leaves arranged in dense rosettes. Native to the southeastern United States and Mexico, it produces tall spikes of fragrant white tubular flowers and is highly drought-tolerant, making it ideal for xeriscaping and coastal gardens.', 'Outdoor', false, false, NULL, true, 'Autumn', true, 'Summer – Early Autumn', 'Moderate', 'Low', '{Well-draining,Sandy,Poor}', 'Southeastern United States and Mexico', 200, 150, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/95129618/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/95129618/medium.jpeg', true, 133334, 133334, 'species');
