879, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Cercidiphyllum japonicum', 'Cercidiphyllum / katsura tree', 6.0, 7.5, false, '{Seeds,"Stem Cuttings"}', true, NULL, '2026-06-07 11:18:55.748872+00', NULL, 'Average', '{full_sun,part_shade}', 'Perennial', NULL, 'Allow soil to dry slightly between waterings during growing season; keep consistently moist but not waterlogged. In autumn and winter, reduce watering frequency.', NULL, NULL, 'Intermediate', 'A deciduous hardwood tree native to Japan and China, prized for its heart-shaped foliage that turns brilliant gold and red in autumn. Known for distinctive candy-like fragrance in fall, it reaches substantial height and creates an elegant canopy in gardens and large landscapes.', 'Outdoor', false, false, NULL, true, 'Summer – Autumn', true, 'Spring', 'Moderate', 'Medium', '{Well-draining,Loamy,Moisture-retaining}', 'Japan and China', 1800, 1200, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/37820164/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/37820164/medium.jpg', true, 133356, 133356, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Rubus allegheniensis', 'Allegheny blackberry', 5.5, 7.0, false, '{"Stem Cuttings",Seeds,Division}', true, NULL, '2026-06-08 01:14:33.368357+00', NULL, 'Average', '{full_sun}', 'Perennial', NULL, 'Check soil moisture at 5 cm depth; allow top layer to dry slightly between waterings during growing season. In established plants, water deeply during dry spells but reduce frequency in winter dormancy.', NULL, NULL, 'Beginner', 'A vigorous native North American bramble producing thorny canes with dark green leaflets and abundant black berries in mid-summer. Highly valued for wild edible fruit production and wildlife habitat.', 'Outdoor', false, false, NULL, true, 'Mid-Summer – Late Summer', true, 'Late Spring – Early Summer', 'Fast', 'Low', '{Well-draining,Sandy,Loamy,Rich}', 'Eastern North America (Appalachian region and adjacent areas)', 200, 150, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/514262843/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/514262843/medium.jpg', true, 82110, 82110, 'species');
INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Sorghum halepense', 'Johnson grass', 6.0, 8.0, true, '{Seeds,Division}', true, NULL, '2026-06-08 01:14:33.368357+00', 'Contains cyanogenic glucosides; young shoots and stressed plants may accumulate toxic levels of cyanide precursors. Livestock should avoid fresh, wilting, or frost-damaged foliage.', 'Minimum', '{full_sun}', 'Perennial', NULL, 'Check soil moisture at 5–7 cm depth. Allow surface to dry between waterings during establishment; mature plants are drought-tolerant and rarely require supplemental irrigation.', NULL, NULL, 'Beginner', 'A robust perennial grass native to North Africa and the Mediterranean, characterized by tall upright culms, broad blade leaves, and open panicles of grain-bearing spikelets. Highly invasive in temperate and subtropical regions due to its resilience and allelopathic seed production; agricultural pest but also exploited for forage and bioenergy.', 'Outdoor', false, true, 'Young shoots and wilted foliage contain cyanogenic glucosides that release cyanide when digested or damaged. Consumption of fresh or stress-damaged plant material may cause acute poisoning.', true, 'Late Summer – Autumn', true, 'Summer – Early Autumn', 'Fast', 'Low', '{Well-draining,Loamy,Rich}', 'Tropical and Mediterranean North Africa, Western Asia', 240, NULL, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/78416044/square.jpg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/78416044/medium.jpg', true, 58387, 58387, 'species');
