INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Yucca flaccida', 'Weak-leaf yucca', 6.0, 7.5, false, '{Seeds,"Offset Separation"}', true, NULL, '2026-06-08 02:59:41.725072+00', NULL, 'Minimum', '{full_sun,part_shade}', 'Perennial', NULL, 'Allow soil to dry completely between waterings. Check soil moisture 5–7 cm deep; water only when completely dry.', NULL, NULL, 'Beginner', 'A low-growing succulent shrub with soft, flexible blue-green leaves and tall spikes of fragrant white bell-shaped flowers. Native to the southeastern United States, it is drought-tolerant and ideal for xeriscaping and ornamental landscapes.', 'Outdoor', false, false, NULL, true, 'Late Summer – Autumn', true, 'Late Spring – Early Summer', 'Slow', 'Low', '{Well-draining,Sandy,Poor}', 'Southeastern United States (Georgia, Florida, South Carolina, North Carolina)', 60, 90, false, 'https://static.inaturalist.org/photos/46257920/square.jpg', 'https://static.inaturalist.org/photos/46257920/medium.jpg', true, 332548, 332548, 'species');
