INSERT INTO public.cached_botanical_records (scientific_name, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, check_depth_description, ideal_humidity_min, ideal_humidity_max, care_difficulty, description, placement, is_tropical, is_toxic_to_humans, human_toxicity_notes, produces_fruit, fruit_season, produces_flowers, flowering_season, growth_rate, maintenance_level, preferred_soil_type, native_region, max_height_cm, max_spread_cm, air_purifying, thumbnail_url, regular_url, thumbnail_fetched, inat_taxon_id, inat_species_id, inat_rank) VALUES ('Tephrosia virginiana', 'Goat''s rue', 6.0, 7.5, true, '{Seeds,Division}', true, NULL, '2026-06-08 01:14:33.679222+00', 'Contains rotenone and other alkaloids; ingestion may cause gastrointestinal upset in livestock and pets. Historically used as a natural pesticide.', 'Average', '{full_sun,part_shade}', 'Perennial', NULL, 'Allow soil to dry moderately between waterings. Check soil 5 cm deep; water when dry to touch in upper layer.', NULL, NULL, 'Beginner', 'A native North American wildflower with delicate pink-purple and white bicolored flowers and fine pinnate foliage. Nitrogen-fixing legume valued for ecological restoration, pollinator support, and ornamental garden use.', 'Outdoor', false, true, 'Contains rotenone; ingestion of plant material may cause gastrointestinal distress. Handle with care; rotenone has pesticidal properties.', true, 'Summer – Autumn', true, 'Summer', 'Moderate', 'Low', '{Well-draining,Sandy,Loamy,Poor}', 'Eastern and Central North America', 60, 45, false, 'https://inaturalist-open-data.s3.amazonaws.com/photos/9191638/square.jpeg', 'https://inaturalist-open-data.s3.amazonaws.com/photos/9191638/medium.jpeg', true, 81836, 81836, 'species');
